/* 对话界面样式 */
.chat-container {
    display: flex;
    flex-direction: column;
    flex: 1;
    min-width: 0;
    background: #f5f7fa;
    overflow: hidden;
    height: 100%;
    position: relative;
}

/* 带 conversation hash 刷新时，在目标对话数据完成恢复前不展示默认新对话状态。
   该状态在同一事件循环内设置，避免“无项目”与欢迎页短暂闪现。 */
.chat-container.is-conversation-restoring #active-tasks-bar,
.chat-container.is-conversation-restoring #chat-messages,
.chat-container.is-conversation-restoring #chat-turn-rail,
.chat-container.is-conversation-restoring #chat-return-latest,
.chat-container.is-conversation-restoring #agent-plan-progress,
.chat-container.is-conversation-restoring #chat-input-container {
    visibility: hidden;
}

/* 会话顶部栏样式 */
.conversation-header {
    background: transparent;
    padding: 8px 24px;
    flex-shrink: 0;
    border-bottom: none;
}

.conversation-header-content {
    display: flex;
    align-items: center;
    justify-content: flex-start;
    gap: 8px;
}

.chat-messages {
    flex: 1;
    overflow-y: auto;
    overflow-x: hidden;
    padding: 24px 24px 24px 64px;
    background: #f5f7fa;
    display: flex;
    flex-direction: column;
    min-height: 0;
    scrollbar-width: thin;
    scrollbar-color: transparent transparent;
}

.chat-messages:hover {
    scrollbar-color: color-mix(in srgb, var(--text-muted) 55%, transparent) transparent;
}

.chat-messages::-webkit-scrollbar {
    width: 4px;
    height: 4px;
}

.chat-messages::-webkit-scrollbar-track {
    background: transparent;
}

.chat-messages::-webkit-scrollbar-thumb {
    background: transparent;
    border-radius: 999px;
}

.chat-messages:hover::-webkit-scrollbar-thumb {
    background: color-mix(in srgb, var(--text-muted) 55%, transparent);
}

.chat-messages:hover::-webkit-scrollbar-thumb:hover {
    background: color-mix(in srgb, var(--text-muted) 80%, transparent);
}
.chat-welcome-empty-state {
    flex: 1 0 auto;
    width: 100%;
    min-height: 100%;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: 48px 24px 96px;
    box-sizing: border-box;
    color: var(--text-primary);
    text-align: center;
}

.chat-welcome-empty-state-title {
    width: min(100%, 900px);
    margin: 0;
    font-size: clamp(1.85rem, 3vw, 3rem);
    font-weight: 400;
    line-height: 1.25;
    letter-spacing: -0.025em;
}

.chat-welcome-project-name {
    display: inline;
    border-bottom: 1px dotted currentColor;
    padding-bottom: 0.08em;
}

.chat-welcome-empty-state-subtitle {
    width: min(100%, 720px);
    margin: 18px 0 0;
    color: var(--text-secondary);
    font-size: clamp(0.95rem, 1.15vw, 1.1rem);
    font-weight: 400;
    line-height: 1.6;
    letter-spacing: 0;
}

.chat-turn-rail {
    position: absolute;
    left: 18px;
    top: calc((100% - var(--chat-composer-total-height, 170px)) / 2);
    z-index: 20;
    width: 44px;
    transform: translateY(-50%);
    pointer-events: none;
}

.chat-turn-rail[hidden] {
    display: none;
}

.chat-turn-rail-markers {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    gap: 0;
    width: 100%;
    box-sizing: border-box;
    max-height: min(48vh, 336px);
    padding: 10px 4px;
    overflow-y: auto;
    overflow-x: hidden;
    overscroll-behavior: contain;
    touch-action: pan-y;
    scrollbar-width: none;
    pointer-events: auto;
}

.chat-turn-rail-markers::-webkit-scrollbar {
    display: none;
}

.chat-turn-rail-marker {
    display: block;
    position: relative;
    width: 36px;
    height: 11px;
    min-height: 11px;
    padding: 0;
    border: 0;
    background: transparent;
    cursor: pointer;
}

.chat-turn-rail-marker::before {
    content: '';
    position: absolute;
    left: 0;
    top: 50%;
    width: 12px;
    height: 3px;
    border-radius: 999px;
    background: #c7cbd1;
    transform: translateY(-50%);
    transform-origin: left center;
    transition: width 0.16s ease, background-color 0.16s ease, opacity 0.16s ease;
}

.chat-turn-rail-marker:hover::before {
    width: 22px;
    background: #7c828b;
}

.chat-turn-rail-marker:focus-visible {
    outline: 2px solid rgba(37, 99, 235, 0.35);
    outline-offset: 3px;
}

.chat-turn-rail-marker.is-active::before {
    width: 12px;
    background: #20242a;
}

.chat-turn-rail-marker.is-active:hover::before {
    width: 22px;
    background: #20242a;
}

.chat-turn-rail-marker.has-pending-new:last-child::before {
    background: var(--primary-color, #2563eb);
    animation: chat-turn-marker-pulse 1.2s ease-in-out infinite;
}

@keyframes chat-turn-marker-pulse {
    0%, 100% { opacity: 0.58; }
    50% { opacity: 1; }
}

.chat-turn-rail-preview {
    position: fixed;
    z-index: 80;
    width: min(520px, calc(100vw - 120px));
    padding: 16px 18px;
    border: 1px solid rgba(15, 23, 42, 0.14);
    border-radius: 18px;
    background: rgba(255, 255, 255, 0.98);
    color: #20242a;
    box-shadow: 0 14px 38px rgba(15, 23, 42, 0.13);
    backdrop-filter: blur(14px);
    pointer-events: auto;
}

.chat-turn-rail-preview[hidden] {
    display: none;
}

.chat-turn-rail-preview-title {
    overflow: hidden;
    color: #20242a;
    font-size: 15px;
    font-weight: 650;
    line-height: 1.4;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.chat-turn-rail-preview-summary {
    display: -webkit-box;
    margin-top: 7px;
    overflow: hidden;
    color: #858a92;
    font-size: 14px;
    font-weight: 500;
    line-height: 1.55;
    -webkit-box-orient: vertical;
    -webkit-line-clamp: 2;
}

.chat-return-latest {
    position: absolute;
    left: 50%;
    bottom: calc(var(--chat-composer-total-height, 170px) + 10px);
    z-index: 24;
    width: 40px;
    height: 40px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    padding: 0;
    border: 1px solid rgba(15, 23, 42, 0.12);
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.97);
    color: #646b75;
    box-shadow: 0 8px 24px rgba(15, 23, 42, 0.12), 0 1px 3px rgba(15, 23, 42, 0.06);
    backdrop-filter: blur(12px);
    cursor: pointer;
    transform: translateX(-50%);
    transition: color 0.16s ease, background 0.16s ease, border-color 0.16s ease, box-shadow 0.16s ease, transform 0.16s ease;
}

.chat-return-latest[hidden] {
    display: none !important;
}

.chat-return-latest:hover {
    border-color: rgba(15, 23, 42, 0.18);
    background: #ffffff;
    color: #303640;
    box-shadow: 0 10px 28px rgba(15, 23, 42, 0.16), 0 2px 5px rgba(15, 23, 42, 0.08);
    transform: translateX(-50%) translateY(-1px);
}

.chat-return-latest:focus-visible {
    outline: 2px solid rgba(37, 99, 235, 0.42);
    outline-offset: 3px;
}

.chat-return-latest-dots {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 4px;
    height: 14px;
}

.chat-return-latest-dot {
    width: 5px;
    height: 5px;
    border-radius: 50%;
    background: currentColor;
}

.chat-return-latest.is-streaming .chat-return-latest-dot {
    animation: chat-return-latest-dot-bounce 0.9s ease-in-out infinite;
}

.chat-return-latest.is-streaming .chat-return-latest-dot:nth-child(2) {
    animation-delay: 0.12s;
}

.chat-return-latest.is-streaming .chat-return-latest-dot:nth-child(3) {
    animation-delay: 0.24s;
}

@keyframes chat-return-latest-dot-bounce {
    0%, 60%, 100% { transform: translateY(0); }
    30% { transform: translateY(-3px); }
}

@media (max-width: 820px) {
    .chat-turn-rail {
        display: none !important;
    }
}

@media (prefers-reduced-motion: reduce) {
    .chat-turn-rail-marker::before {
        transition: none;
    }

    .chat-turn-rail-marker.has-pending-new:last-child::before {
        animation: none;
    }

    .chat-return-latest,
    .chat-return-latest.is-streaming .chat-return-latest-dot {
        transition: none;
        animation: none;
    }
}

.message {
    margin-bottom: 24px;
    display: flex;
    align-items: flex-start;
    gap: 0;
    animation: fadeIn 0.3s ease-in;
    width: 100%;
}

@keyframes fadeIn {
    from {
        opacity: 0;
        transform: translateY(10px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

.message.user {
    justify-content: flex-end;
}

.message.system {
    justify-content: center;
    margin-bottom: 16px;
}

.message-content {
    flex: 0 1 auto;
    max-width: 70%;
    min-width: 120px;
    display: flex;
    flex-direction: column;
    overflow-x: visible;
    overflow-y: visible;
    width: 100%;
}

.message.user .message-content {
    align-items: flex-end;
    margin-left: auto;
    width: auto;
    max-width: min(78%, 760px);
}

.message.assistant .message-content {
    align-items: flex-start;
    margin-right: auto;
    min-width: 0;
    max-width: min(100%, 920px);
}

.message.system .message-content {
    max-width: 75%;
    align-items: stretch;
    margin: 0;
}

.message-bubble {
    padding: 12px 16px;
    border-radius: 8px;
    word-wrap: break-word;
    word-break: break-word;
    line-height: 1.6;
    box-shadow: var(--shadow-sm);
    overflow-x: auto;
    overflow-y: visible;
    max-width: 100%;
    -webkit-overflow-scrolling: touch;
    position: relative;
}

/* Markdown 样式 */
.message-bubble p {
    margin: 0.5em 0;
}

.message-bubble p:first-child {
    margin-top: 0;
}

.message-bubble p:last-child {
    margin-bottom: 0;
}

.message-bubble strong,
.message-bubble b {
    font-weight: 600;
    color: inherit;
}

.message-bubble em,
.message-bubble i {
    font-style: italic;
}

.message-bubble code {
    background: rgba(0, 0, 0, 0.05);
    padding: 2px 6px;
    border-radius: 3px;
    font-family: 'Monaco', 'Menlo', 'Ubuntu Mono', monospace;
    font-size: 0.9em;
}

.message.user .message-bubble code {
    background: rgba(255, 255, 255, 0.2);
}

.message-bubble pre {
    background: rgba(0, 0, 0, 0.05);
    padding: 12px;
    border-radius: 6px;
    overflow-x: auto;
    margin: 0.5em 0;
    font-family: 'Monaco', 'Menlo', 'Ubuntu Mono', monospace;
    font-size: 0.875em;
    line-height: 1.5;
}

.message.user .message-bubble pre {
    background: rgba(255, 255, 255, 0.15);
}

.message-bubble pre code {
    background: none;
    padding: 0;
}

.message-bubble ul,
.message-bubble ol {
    margin: 0.5em 0;
    padding-left: 1.5em;
}

.message-bubble li {
    margin: 0.25em 0;
}

.message-bubble blockquote {
    border-left: 3px solid var(--border-color);
    padding-left: 1em;
    margin: 0.5em 0;
    color: var(--text-secondary);
}

.message-bubble h1,
.message-bubble h2,
.message-bubble h3,
.message-bubble h4,
.message-bubble h5,
.message-bubble h6 {
    margin: 0.8em 0 0.4em 0;
    font-weight: 600;
    line-height: 1.3;
}

.message-bubble h1:first-child,
.message-bubble h2:first-child,
.message-bubble h3:first-child,
.message-bubble h4:first-child,
.message-bubble h5:first-child,
.message-bubble h6:first-child {
    margin-top: 0;
}

.message-bubble h1 {
    font-size: 1.5em;
}

.message-bubble h2 {
    font-size: 1.3em;
}

.message-bubble h3 {
    font-size: 1.1em;
}

.message-bubble hr {
    border: none;
    border-top: 1px solid var(--border-color);
    margin: 1em 0;
}

.message-bubble a {
    color: var(--accent-color);
    text-decoration: none;
}

.message-bubble a:hover {
    text-decoration: underline;
}

.message.user .message-bubble a {
    color: rgba(255, 255, 255, 0.9);
    text-decoration: underline;
}

/* Markdown 表格样式 */
/* 表格包装容器，为每个表格提供独立的横向滚动 */
.message-bubble .table-wrapper {
    width: 100%;
    overflow-x: auto;
    overflow-y: visible;
    margin: 1em 0;
    -webkit-overflow-scrolling: touch;
    /* 自定义滚动条样式 */
    scrollbar-width: thin;
    scrollbar-color: rgba(0, 0, 0, 0.2) transparent;
}

.message-bubble .table-wrapper::-webkit-scrollbar {
    height: 8px;
}

.message-bubble .table-wrapper::-webkit-scrollbar-track {
    background: transparent;
    border-radius: 4px;
}

.message-bubble .table-wrapper::-webkit-scrollbar-thumb {
    background: rgba(0, 0, 0, 0.2);
    border-radius: 4px;
}

.message-bubble .table-wrapper::-webkit-scrollbar-thumb:hover {
    background: rgba(0, 0, 0, 0.3);
}

/* 表格本身，允许根据内容自动扩展宽度 */
.message-bubble table {
    width: auto;
    min-width: 100%;
    border-collapse: collapse;
    margin: 0;
    font-size: 0.9em;
    display: table;
    table-layout: auto;
}

/* 确保表格能够超出容器宽度 */
.message-bubble table * {
    box-sizing: border-box;
}

/* 确保表格内容不会被压缩 */
.message-bubble table colgroup,
.message-bubble table col {
    width: auto;
}

.message-bubble table thead {
    background: var(--bg-secondary);
}

.message-bubble table th {
    padding: 10px 12px;
    text-align: left;
    font-weight: 600;
    color: var(--text-primary);
    border-bottom: 2px solid var(--border-color);
    white-space: nowrap;
    min-width: fit-content;
}

.message-bubble table td {
    padding: 10px 12px;
    border-bottom: 1px solid var(--border-color);
    color: var(--text-primary);
    width: auto;
    min-width: 120px;
    max-width: none;
    vertical-align: top;
    /* 允许文字换行，避免重叠和溢出 */
    white-space: normal;
    word-wrap: break-word;
    word-break: break-word;
    overflow-wrap: break-word;
    hyphens: auto;
    line-height: 1.5;
}

.message-bubble table tbody tr:hover {
    background: var(--bg-secondary);
}

.message-bubble table tbody tr:last-child td {
    border-bottom: none;
}

/* 消息气泡相对定位，用于放置复制按钮 */
.message-bubble {
    position: relative;
}

/* 消息复制按钮 - 与时间戳同一行 */
.message-copy-btn {
    position: static;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 28px;
    height: 28px;
    padding: 0;
    background: transparent;
    border: 1px solid transparent;
    border-radius: 6px;
    color: var(--text-secondary, #888);
    cursor: pointer;
    opacity: 0.72;
    flex-shrink: 0;
    transition: opacity 0.2s ease, color 0.2s ease, background 0.2s ease, border-color 0.2s ease;
}

.message-copy-btn:hover {
    color: var(--accent-color, #0066ff);
    background: rgba(0, 102, 255, 0.07);
    border-color: rgba(0, 102, 255, 0.14);
    opacity: 1;
}

.message-copy-btn:active {
    background: rgba(0, 102, 255, 0.11);
}

.message-copy-btn svg {
    width: 16px;
    height: 16px;
    flex-shrink: 0;
}

.message-copy-btn:focus-visible {
    opacity: 1;
    outline: 2px solid var(--accent-color, #0066ff);
    outline-offset: 1px;
}

.message-copy-btn span {
    display: none;
}

/* 时间戳 + 删除本轮（与气泡分离，和「展开详情」同一视觉层级） */
.message-meta-footer {
    display: flex;
    flex-direction: row;
    align-items: center; /* 与时间戳、删除钮统一垂直居中 */
    gap: 8px;
    margin-top: 6px;
    flex-wrap: wrap;
    width: 100%;
    min-height: 28px;
}

.message.user .message-meta-footer {
    justify-content: flex-end;
}

.message.assistant .message-meta-footer {
    justify-content: flex-start;
}

.message-delete-turn-btn {
    position: static;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 28px;
    height: 28px;
    padding: 0;
    border: 1px solid transparent;
    border-radius: 6px;
    background: transparent;
    color: var(--text-secondary, #888);
    cursor: pointer;
    opacity: 0.5;
    flex-shrink: 0;
    transition: opacity 0.2s ease, color 0.2s ease, background 0.2s ease, border-color 0.2s ease;
}

.message:hover .message-meta-footer .message-delete-turn-btn {
    opacity: 0.85;
}

.message-delete-turn-btn:hover {
    color: #c62828;
    background: rgba(198, 40, 40, 0.07);
    border-color: rgba(198, 40, 40, 0.15);
    opacity: 1;
}

.message-delete-turn-btn:focus-visible {
    opacity: 1;
    outline: 2px solid var(--accent-color, #0066ff);
    outline-offset: 1px;
}

/* 与删除钮同一行时：去掉时间戳默认 margin-top，避免文字偏低、图标显「高」 */
.message-meta-footer .message-time {
    margin-top: 0;
    display: inline-flex;
    align-items: center;
    min-height: 28px;
    line-height: 1.3;
}

.message-delete-turn-btn svg {
    display: block;
    flex-shrink: 0;
}

@media (hover: none) {
    .message-delete-turn-btn {
        opacity: 0.65;
    }
}

/* 用户消息中的表格样式 */
.message.user .message-bubble .table-wrapper {
    scrollbar-color: rgba(255, 255, 255, 0.3) transparent;
}

.message.user .message-bubble .table-wrapper::-webkit-scrollbar-thumb {
    background: rgba(255, 255, 255, 0.3);
}

.message.user .message-bubble .table-wrapper::-webkit-scrollbar-thumb:hover {
    background: rgba(255, 255, 255, 0.4);
}

.message.user .message-bubble table {
    color: rgba(255, 255, 255, 0.95);
}

.message.user .message-bubble table thead {
    background: rgba(255, 255, 255, 0.15);
}

.message.user .message-bubble table th {
    color: rgba(255, 255, 255, 0.95);
    border-bottom-color: rgba(255, 255, 255, 0.3);
}

.message.user .message-bubble table td {
    color: rgba(255, 255, 255, 0.9);
    border-bottom-color: rgba(255, 255, 255, 0.2);
}

.message.user .message-bubble table tbody tr:hover {
    background: rgba(255, 255, 255, 0.1);
}

.message.user .message-bubble {
    background: var(--bg-tertiary);
    color: var(--text-primary);
    border: 1px solid transparent;
    border-radius: 20px;
    box-shadow: none;
}

.message.assistant:not(.progress-message):not(.assistant-turn-with-process) .message-bubble {
    background: transparent;
    color: var(--text-primary);
    border: 0;
    border-radius: 0;
    box-shadow: none;
    padding: 0;
}

.message.assistant.assistant-not-finalized .message-bubble {
    border-color: rgba(245, 124, 0, 0.28);
    border-left: 4px solid #f57c00;
    background: linear-gradient(90deg, rgba(245, 124, 0, 0.08), rgba(245, 124, 0, 0.035));
    box-shadow: 0 6px 18px rgba(245, 124, 0, 0.08);
}

.message.assistant.assistant-not-finalized .message-bubble strong:first-child {
    color: #b45309;
}

.message.assistant .message-bubble pre {
    margin: 0;
    white-space: pre-wrap;
    word-wrap: break-word;
    font-family: inherit;
}

.message.system .message-bubble {
    background: var(--bg-tertiary);
    color: var(--text-secondary);
    border: 1px solid var(--border-color);
    text-align: left;
    font-size: 0.875rem;
    padding: 10px 16px;
    width: 100%;
}

.message-time {
    font-size: 0.6875rem;
    color: var(--text-muted);
    margin-top: 4px;
    padding: 0 2px;
    font-weight: 400;
}

/* MCP调用区域 */
.mcp-call-section {
    margin-top: 12px;
    padding-top: 12px;
    border-top: 1px solid var(--border-color);
    width: 100%;
    min-width: 0;
    max-width: 100%;
    box-sizing: border-box;
}

.mcp-call-label {
    font-size: 0.75rem;
    color: var(--text-secondary);
    margin-bottom: 8px;
    display: flex;
    align-items: center;
    gap: 6px;
    font-weight: 500;
}

.mcp-call-label::before {
    content: '';
    width: 4px;
    height: 4px;
    background: var(--accent-color);
    border-radius: 50%;
    display: inline-block;
    flex-shrink: 0;
}

.mcp-call-toolbar {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
    align-items: center;
}

.mcp-tool-list {
    display: none;
    flex-wrap: wrap;
    gap: 6px;
    margin-top: 8px;
    width: 100%;
}

.mcp-tool-list.expanded {
    display: flex;
}

.mcp-tools-toggle-btn {
    background: rgba(25, 118, 210, 0.1) !important;
    border-color: rgba(25, 118, 210, 0.35) !important;
    color: #1976d2 !important;
}

.mcp-call-toolbar .process-detail-btn,
.mcp-call-toolbar .mcp-tools-toggle-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 6px;
    min-height: 32px;
    padding: 6px 12px;
    font-size: 0.8125rem;
    font-weight: 500;
    line-height: 1.25;
    box-sizing: border-box;
    white-space: nowrap;
    vertical-align: middle;
}

.mcp-call-toolbar .process-detail-btn span,
.mcp-call-toolbar .mcp-tools-toggle-btn span {
    display: inline-flex;
    align-items: center;
    line-height: 1.25;
}

.mcp-tools-toggle-btn:hover {
    background: rgba(25, 118, 210, 0.18) !important;
    border-color: #1976d2 !important;
    color: #1565c0 !important;
}

.process-detail-btn {
    background: rgba(156, 39, 176, 0.1) !important;
    border-color: rgba(156, 39, 176, 0.3) !important;
    color: #9c27b0 !important;
}

.mcp-call-toolbar .process-detail-btn {
    display: inline-flex;
    align-items: center;
    gap: 6px;
}

.process-detail-btn:hover {
    background: rgba(156, 39, 176, 0.2) !important;
    border-color: #9c27b0 !important;
    color: #7b1fa2 !important;
}

.process-detail-btn span {
    display: inline-flex;
    align-items: center;
    gap: 4px;
}

.process-details-container {
    margin-top: 12px;
    padding-top: 12px;
    border-top: 1px solid var(--border-color);
    width: 100%;
    min-width: 0;
    max-width: 100%;
    box-sizing: border-box;
}

.process-details-content {
    position: relative;
    width: 100%;
    min-width: 0;
    max-width: 100%;
}

.process-details-return-latest-host {
    position: relative;
}

.process-details-content .progress-timeline {
    max-height: 0;
    overflow: hidden;
    transition: max-height 0.3s ease;
    opacity: 0;
}

.process-details-content .progress-timeline.expanded {
    max-height: min(70vh, 760px);
    overflow-x: hidden;
    overflow-y: auto;
    opacity: 1;
    margin-top: 12px;
    scroll-behavior: smooth;
    /* 详情内部可滚动时优先滚详情；到达边界或运行中取消内层滚动时，
       继续把滚轮自然传给外层 #chat-messages，避免鼠标悬停卡片后“滚不动”。 */
    overscroll-behavior: auto;
    scrollbar-gutter: stable;
}

.process-details-return-latest {
    position: absolute;
    right: 18px;
    bottom: 16px;
    z-index: 7;
    width: 34px;
    height: 34px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    padding: 0;
    border: 1px solid rgba(15, 23, 42, 0.14);
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.96);
    color: #5f6875;
    box-shadow: 0 8px 22px rgba(15, 23, 42, 0.14), 0 1px 3px rgba(15, 23, 42, 0.08);
    backdrop-filter: blur(10px);
    cursor: pointer;
    transition: color 0.16s ease, background 0.16s ease, border-color 0.16s ease, box-shadow 0.16s ease, transform 0.16s ease;
}

.process-details-return-latest[hidden] {
    display: none !important;
}

.process-details-return-latest:hover {
    border-color: rgba(37, 99, 235, 0.3);
    background: #ffffff;
    color: var(--accent-color, #0b6cff);
    box-shadow: 0 10px 26px rgba(15, 23, 42, 0.18), 0 2px 5px rgba(15, 23, 42, 0.1);
    transform: translateY(-1px);
}

.process-details-return-latest:focus-visible {
    outline: 2px solid rgba(37, 99, 235, 0.42);
    outline-offset: 3px;
}

.process-details-return-latest svg {
    width: 18px;
    height: 18px;
}

.process-details-return-latest.has-pending-new::after,
.process-details-return-latest.is-streaming::after {
    content: "";
    position: absolute;
    top: 5px;
    right: 5px;
    width: 7px;
    height: 7px;
    border: 2px solid rgba(255, 255, 255, 0.96);
    border-radius: 50%;
    background: var(--accent-color, #0b6cff);
