    height: 36px;
    padding: 0 32px 0 10px;
    font-size: 0.8125rem;
    border: 1px solid var(--border-color, #e2e8f0);
    border-radius: 8px;
    background: var(--card-bg, #fff);
    color: var(--text-color, #2d3748);
}

.session-settings-native-select {
    position: absolute;
    opacity: 0;
    pointer-events: none;
    width: 1px;
    height: 1px;
}

.session-settings-select {
    position: relative;
    width: 100%;
}

.session-settings-select-trigger {
    width: 100%;
    height: 36px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 8px;
    padding: 0 10px;
    border: 1px solid var(--border-color, #e2e8f0);
    border-radius: 8px;
    background: #fff;
    color: var(--text-color, #2d3748);
    font-size: 13px;
    font-weight: 600;
    text-align: left;
    cursor: pointer;
    transition: border-color 0.15s ease, box-shadow 0.15s ease, background 0.15s ease;
}

.session-settings-select-trigger:hover {
    border-color: rgba(49, 130, 206, 0.38);
    background: #fbfdff;
}

.session-settings-select-trigger:focus-visible,
.session-settings-select.open .session-settings-select-trigger {
    outline: none;
    border-color: var(--accent-color, #3182ce);
    box-shadow: 0 0 0 3px rgba(49, 130, 206, 0.14);
}

.session-settings-select-value {
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.session-settings-select-caret {
    flex-shrink: 0;
    color: var(--text-muted, #718096);
    font-size: 17px;
    line-height: 1;
    transform: translateY(-1px);
    transition: transform 0.15s ease, color 0.15s ease;
}

.session-settings-select.open .session-settings-select-caret {
