}

html[data-theme="dark"] .login-card .login-submit:active {
    background: linear-gradient(135deg, #1d4ed8 0%, #1e40af 100%) !important;
    border-color: rgba(96, 165, 250, 0.34) !important;
    box-shadow:
        0 3px 8px rgba(2, 6, 23, 0.3),
