/* 模态框样式 */
.modal {
    display: none;
    position: fixed;
    z-index: 1000;
    left: 0;
    top: 0;
    width: 100%;
    height: 100%;
    background-color: rgba(15, 23, 42, 0.52);
    overflow: auto;
    animation: fadeIn 0.15s ease-out;
}

.modal-content {
    background-color: var(--bg-primary);
    margin: 5% auto;
    padding: 0;
    border-radius: 12px;
    width: 90%;
    max-width: 900px;
    max-height: 85vh;
    display: flex;
    flex-direction: column;
    box-shadow: var(--shadow-lg);
    border: 1px solid var(--border-color);
    animation: slideDown 0.18s ease-out;
    overflow: hidden;
    contain: layout style paint;
}

@keyframes slideDown {
    from {
        opacity: 0;
        transform: translateY(-20px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

.modal-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 24px 28px;
    border-bottom: 1px solid var(--border-color);
    background: linear-gradient(135deg, #ffffff 0%, #f8f9fa 100%);
    border-top-left-radius: 16px;
    border-top-right-radius: 16px;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.04);
}

.modal-header h2 {
    margin: 0;
    font-size: 1.5rem;
    font-weight: 600;
    color: var(--text-primary);
    background: linear-gradient(135deg, var(--accent-color) 0%, #0052cc 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
    /* 允许标题在 flex 中收缩/换行，避免把右侧按钮挤压变形 */
    flex: 1 1 auto;
    min-width: 0;
    overflow-wrap: anywhere;
}

/* 统一关闭按钮：32×32 正方形容器 + 16px 居中图标；默认无背景，hover 显示 #f2f3f5 */
.modal-close,
.projects-modal-close,
.role-selection-panel-close,
.attack-chain-details-close,
.c2-modal-close {
    width: 32px;
    height: 32px;
    min-width: 32px;
    min-height: 32px;
    padding: 0;
    margin: 0;
    border: none;
    border-radius: 8px;
    background: transparent;
    color: var(--close-btn-color);
    cursor: pointer;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    line-height: 0;
    font-size: 0;
    transition: background 0.15s ease, color 0.15s ease;
    -webkit-tap-highlight-color: transparent;
    appearance: none;
}

.modal-close svg,
.projects-modal-close svg,
.role-selection-panel-close svg,
.attack-chain-details-close svg,
.c2-modal-close svg {
    width: 16px;
    height: 16px;
    display: block;
    flex-shrink: 0;
}

.modal-close:not(:has(svg))::before,
.projects-modal-close:not(:has(svg))::before,
.c2-modal-close:not(:has(svg))::before {
    content: '';
    display: block;
    width: 16px;
    height: 16px;
    background-color: currentColor;
    -webkit-mask-image: var(--icon-close-mask);
    mask-image: var(--icon-close-mask);
    -webkit-mask-size: contain;
    mask-size: contain;
    -webkit-mask-repeat: no-repeat;
    mask-repeat: no-repeat;
    -webkit-mask-position: center;
    mask-position: center;
}

.modal-close:hover,
.projects-modal-close:hover,
.role-selection-panel-close:hover,
.attack-chain-details-close:hover,
.c2-modal-close:hover {
    background: var(--close-btn-bg-hover);
    color: var(--close-btn-color);
}

.modal-close:active,
.projects-modal-close:active,
.role-selection-panel-close:active,
.attack-chain-details-close:active,
.c2-modal-close:active {
    background: var(--close-btn-bg-active);
    color: var(--close-btn-color);
}

