}

.tool-item {
    display: flex;
    align-items: flex-start;
    gap: 12px;
    padding: 10px 12px;
    border-radius: 6px;
    transition: background 0.2s;
    cursor: pointer;
}

.tool-item:hover {
    background: var(--bg-tertiary);
}

.tool-item input[type="checkbox"] {
    width: 18px;
    height: 18px;
    margin-top: 2px;
    cursor: pointer;
    accent-color: var(--accent-color);
    flex-shrink: 0;
}

.tool-item > .theme-checkbox {
    --theme-checkbox-size: 18px;
}

.tool-item-info {
    flex: 1;
    min-width: 0;
}

.tool-item-name {
    font-weight: 500;
    color: var(--text-primary);
    font-size: 0.9375rem;
    margin-bottom: 4px;
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
}

.tool-resident-toggle {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    font-size: 0.75rem;
    color: var(--text-secondary);
    border: 1px solid var(--border-color);
    border-radius: 12px;
    padding: 2px 8px;
    background: var(--bg-secondary);
    cursor: pointer;
}

.tool-resident-toggle input[type="checkbox"] {
    width: 14px;
    height: 14px;
    margin: 0;
}

.tool-resident-toggle .theme-checkbox {
    --theme-checkbox-size: 14px;
    border-radius: 3px;
}

.external-tool-badge {
    display: inline-flex;
    align-items: center;
    padding: 2px 8px;
    background: rgba(255, 152, 0, 0.12);
    border: 1px solid rgba(255, 152, 0, 0.3);
    border-radius: 12px;
    font-size: 0.75rem;
    font-weight: 600;
    color: #ff9800;
    white-space: nowrap;
}

.tool-item-desc {
    font-size: 0.8125rem;
    color: var(--text-secondary);
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

/* 展开图标 */
.tool-expand-icon {
    font-size: 0.625rem;
    color: var(--text-tertiary);
    transition: transform 0.2s;
    user-select: none;
    flex-shrink: 0;
}

/* 展开后的详情面板 */
.tool-item-detail {
    margin-top: 8px;
    padding: 12px;
    background: var(--bg-tertiary);
    border-radius: 8px;
    border: 1px solid var(--border-color);
