}

.batch-queue-item__mid-left {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 8px 12px;
    flex: 1 1 200px;
    min-width: 0;
}

.batch-queue-item__sublabel {
    font-size: 0.8125rem;
    color: var(--text-primary);
    line-height: 1.35;
}

.batch-queue-item__mid-right {
    flex: 0 1 200px;
    min-width: 140px;
    display: flex;
    flex-direction: column;
    gap: 4px;
    align-items: stretch;
}

.batch-queue-progress-bar--list {
    height: 8px;
}

.batch-queue-item__pct {
    font-size: 0.75rem;
    color: var(--text-secondary);
    text-align: right;
}

.batch-queue-item__pct-frac {
    font-variant-numeric: tabular-nums;
}

.batch-queue-statsline {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 4px 0;
    font-size: 0.75rem;
    color: var(--text-secondary);
    padding-top: 8px;
}

.batch-queue-statsline__sep {
    margin: 0 8px;
    opacity: 0.4;
    user-select: none;
