.batch-queue-detail-info .detail-value {
    font-size: 0.9375rem;
    color: var(--text-primary);
    font-weight: 500;
    word-break: break-word;
}

.batch-queue-detail-info .detail-value code {
    font-family: 'Monaco', 'Menlo', 'Ubuntu Mono', monospace;
    font-size: 0.875rem;
    background: var(--bg-secondary);
    padding: 2px 6px;
    border-radius: 4px;
    color: var(--accent-color);
}

/* 批量队列详情弹窗：标题很长时避免挤压右侧按钮 */
#batch-queue-detail-modal .modal-header {
    align-items: flex-start;
    gap: 12px;
}

#batch-queue-detail-modal .modal-header > div {
    flex-shrink: 0;
}

#batch-queue-detail-modal .modal-header-actions {
    flex-direction: row;
    width: auto;
    flex-wrap: wrap;
    justify-content: flex-end;
}

#batch-queue-detail-modal .modal-header-actions button {
    white-space: nowrap;
}

.batch-queue-tasks-list {
    max-height: 500px;
    overflow-y: auto;
}

.batch-queue-tasks-list h4 {
    margin: 0 0 16px 0;
    font-size: 1rem;
    font-weight: 600;
    color: var(--text-primary);
}

.batch-queue-detail-layout + .batch-queue-tasks-list h4 {
    margin-top: 4px;
}

.batch-queue-item__title-col {
    flex: 1;
    min-width: 0;
}

.batch-task-item {
    background: var(--bg-primary);
    border: 1px solid var(--border-color);
    border-radius: 8px;
    padding: 12px 14px;
    margin-bottom: 10px;
    transition: all 0.2s ease;
}

.batch-task-item:hover {
    box-shadow: var(--shadow-sm);
}

.batch-task-item-active {
    border-color: var(--accent-color);
    background: rgba(0, 102, 255, 0.02);
}

.batch-task-header {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 8px;
    flex-wrap: wrap;
}

.batch-task-header .btn-small {
    margin-left: 0;
    flex-shrink: 0;
}

.batch-task-header .batch-task-edit-btn {
    /* 仅把「编辑」(首个操作按钮)推到最右，避免多个按钮都 margin-left:auto 导致挤压/错位 */
    margin-left: auto;
}

.batch-task-header .batch-task-edit-btn--push {
    margin-left: auto;
}

.batch-task-header .batch-task-run-btn {
    flex-shrink: 0;
}

.batch-task-header .batch-task-run-btn:disabled {
    opacity: 0.55;
    cursor: not-allowed;
}

.batch-task-header .batch-task-delete-btn {
    margin-left: 8px;
}

.batch-task-index {
    font-weight: 600;
    color: var(--text-secondary);
    min-width: 30px;
}

.batch-task-status {
    display: inline-flex;
    align-items: center;
    padding: 2px 8px;
    border-radius: 8px;
    font-size: 0.75rem;
    font-weight: 500;
    white-space: nowrap;
}

.batch-task-status-pending {
    background: rgba(108, 117, 125, 0.1);
    color: var(--text-secondary);
}

.batch-task-status-running {
    background: rgba(0, 123, 255, 0.1);
    color: var(--accent-color);
}

.batch-task-status-completed {
    background: rgba(40, 167, 69, 0.1);
    color: var(--success-color);
}

.batch-task-status-failed {
    background: rgba(220, 53, 69, 0.1);
    color: var(--error-color);
}

.batch-task-status-cancelled {
    background: rgba(108, 117, 125, 0.1);
    color: var(--text-secondary);
}

.batch-task-message {
    flex: 1;
    font-size: 0.875rem;
    color: var(--text-primary);
    word-break: break-word;
}

.batch-task-time {
    font-size: 0.75rem;
    color: var(--text-secondary);
    margin-top: 4px;
}

.batch-task-error {
    font-size: 0.8125rem;
    color: var(--error-color);
    margin-top: 8px;
    padding: 8px;
    background: rgba(220, 53, 69, 0.05);
    border-radius: 4px;
    border-left: 3px solid var(--error-color);
}

.batch-task-result {
    font-size: 0.8125rem;
    color: var(--text-primary);
    margin-top: 8px;
    padding: 8px;
    background: var(--bg-secondary);
    border-radius: 4px;
    max-height: 150px;
    overflow-y: auto;
    word-break: break-word;
}

.batch-import-stats {
    display: none;
    padding: 8px 12px;
    background: rgba(0, 102, 255, 0.05);
    border: 1px solid rgba(0, 102, 255, 0.2);
    border-radius: 6px;
    font-size: 0.875rem;
    color: var(--accent-color);
}

.batch-import-stat {
    font-weight: 500;
}

@media (max-width: 768px) {
    .batch-queue-header {
        flex-direction: column;
        align-items: flex-start;
    }

    .batch-queue-item__inner--grid {
        grid-template-columns: 1fr auto;
        grid-template-areas:
            "lead actions"
            "cluster cluster"
            "progress progress";
        row-gap: 8px;
    }

    .batch-queue-item--no-actions .batch-queue-item__inner--grid {
        grid-template-columns: 1fr;
        grid-template-areas:
            "lead"
            "cluster"
            "progress";
    }

    .batch-queue-item__cluster {
        align-items: flex-start;
        text-align: left;
        max-width: none;
        justify-self: stretch;
    }

    .batch-queue-item__status-inline {
        justify-content: flex-start;
        width: 100%;
    }

    .batch-queue-item__inner--grid .batch-queue-item__pct {
        text-align: left;
    }

    .batch-queue-item__idline--lead {
        white-space: normal;
        overflow: visible;
        text-overflow: clip;
    }

    .batch-queue-item__top {
        flex-wrap: wrap;
        gap: 8px 10px;
    }

    .batch-queue-item__mid {
        flex-direction: column;
        align-items: stretch;
    }

    .batch-queue-item__mid-right {
        flex: 1 1 auto;
        max-width: none;
    }

    .batch-queue-item__pct {
        text-align: left;
    }

    .batch-queue-card-row {
        flex-direction: column;
    }

    .batch-queue-side {
        flex-basis: auto;
        width: 100%;
        align-items: stretch;
    }

    .batch-queue-delete-btn {
        align-self: flex-end;
    }

    .batch-queue-progress-stack {
        min-width: 0;
    }

    .batch-queue-progress {
        width: 100%;
    }

    .batch-queue-stats {
        flex-direction: column;
        gap: 8px;
    }

    .batch-queue-stats--pills {
        justify-content: flex-start;
    }
    
    .batch-task-header {
        flex-direction: column;
        align-items: flex-start;
    }
}

/* 漏洞管理页面样式 */
.page-header-actions .btn-secondary.btn-delete {
    color: var(--error-color, #dc3545);
}

.page-header-actions .btn-secondary.btn-delete:hover {
    color: #c82333;
    border-color: rgba(220, 53, 69, 0.35);
    background: rgba(220, 53, 69, 0.06);
}

.vulnerability-dashboard {
    margin-bottom: 24px;
}

.dashboard-stats {
    display: grid;
    grid-template-columns: repeat(6, minmax(0, 1fr));
    gap: 12px;
    margin-bottom: 20px;
}

@media (max-width: 1200px) {
    .dashboard-stats {
        grid-template-columns: repeat(3, minmax(0, 1fr));
    }
}

@media (max-width: 640px) {
    .dashboard-stats {
