    border-color: rgba(245, 158, 11, 0.20);
}

.dashboard-recent-vuln-status.st-fixed {
    background: rgba(34, 197, 94, 0.10);
    color: #15803d;
    border-color: rgba(34, 197, 94, 0.20);
}

.dashboard-recent-vuln-status.st-fp {
    background: rgba(148, 163, 184, 0.16);
