}

.dashboard-tools-bar-value {
    font-weight: 600;
    color: var(--text-secondary);
    font-size: 0.8125rem;
    text-align: right;
    font-variant-numeric: tabular-nums;
}

.dashboard-tools-bar-tooltip {
    display: none;
    position: fixed;
    left: 0;
    top: 0;
    z-index: 10000;
    max-width: 320px;
    padding: 6px 10px;
