    display: flex;
    align-items: center;
    gap: 8px;
    width: 100%;
    padding: 8px 10px;
    border: none;
    border-radius: 6px;
    background: transparent;
    color: var(--text-primary);
    font-size: 0.8125rem;
    font-family: inherit;
    cursor: pointer;
    text-align: left;
    transition: background 0.12s ease, color 0.12s ease;
}

.vuln-status-picker-option:hover {
    background: var(--bg-secondary);
}

.vuln-status-picker-option.is-selected {
    background: rgba(0, 102, 255, 0.08);
    color: var(--accent-color);
    font-weight: 500;
}

.vuln-status-picker-check {
    width: 14px;
    flex-shrink: 0;
    opacity: 0;
    font-size: 0.75rem;
    line-height: 1;
    color: var(--accent-color);
}

.vuln-status-picker-option.is-selected .vuln-status-picker-check {
    opacity: 1;
}

.vuln-status-picker-label {
    flex: 1;
    min-width: 0;
}

.vulnerability-card--removing {
    opacity: 0;
    transform: scale(0.98);
    pointer-events: none;
    transition: opacity 0.18s ease, transform 0.18s ease;
}

.vulnerability-date {
    font-size: 0.75rem;
    color: var(--text-muted);
}

.vulnerability-actions {
    display: flex;
    gap: 8px;
}

.vulnerability-content {
    margin-top: 16px;
    padding-left: 24px;
    animation: slideDown 0.2s ease;
}

@keyframes slideDown {
    from {
        opacity: 0;
        max-height: 0;
    }
    to {
        opacity: 1;
        max-height: 5000px;
    }
}

.vulnerability-description {
    margin-bottom: 16px;
    color: var(--text-primary);
    line-height: 1.6;
}

.vulnerability-details {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 14px 16px;
    margin-bottom: 16px;
    padding: 12px;
    background: var(--bg-secondary);
    border-radius: 6px;
    align-items: start;
}

/* 元数据条数为奇数时，最后一项占满一行，长 URL/队列 ID 更易读 */
.vulnerability-details .vuln-detail-field:last-child:nth-child(odd) {
    grid-column: 1 / -1;
}

@media (max-width: 768px) {
    .vulnerability-details {
        grid-template-columns: 1fr;
    }

    .vulnerability-details .vuln-detail-field:last-child:nth-child(odd) {
        grid-column: auto;
    }
}

/* 漏洞详情字段：标签与值分行，长 ID/URL 可换行、可选中复制 */
.vuln-detail-field {
    min-width: 0;
    font-size: 0.875rem;
}

.vuln-detail-field__label {
    color: var(--text-secondary);
    font-weight: 600;
    font-size: 0.75rem;
    margin-bottom: 6px;
    text-transform: none;
    letter-spacing: normal;
}

.vuln-detail-field__row {
    display: flex;
    align-items: flex-start;
    gap: 8px;
    min-width: 0;
}

.vuln-detail-field-value {
    flex: 1;
    min-width: 0;
    margin: 0;
    padding: 8px 10px;
    border-radius: 6px;
    background: var(--bg-secondary);
    border: 1px solid var(--border-color);
    font-size: 0.8125rem;
    line-height: 1.45;
    word-break: break-word;
    overflow-wrap: anywhere;
    white-space: pre-wrap;
    user-select: text;
    -webkit-user-select: text;
    color: var(--text-primary);
    font-family: 'Monaco', 'Menlo', 'Ubuntu Mono', 'Consolas', monospace;
}

html[data-theme="dark"] .vulnerability-details code.vuln-detail-field-value {
    background: var(--bg-secondary) !important;
    color: var(--text-primary);
    border-color: var(--border-color);
}

.vuln-detail-field__actions {
    display: flex;
    flex-shrink: 0;
    align-items: flex-start;
    gap: 2px;
    margin-top: 2px;
}

.vuln-detail-field__copy,
.vuln-detail-field__action {
    flex-shrink: 0;
    padding: 6px;
    line-height: 0;
    border-radius: 6px;
    color: var(--text-secondary);
    border: 1px solid transparent;
    background: transparent;
    cursor: pointer;
}

.vuln-detail-field__copy:hover,
.vuln-detail-field__action:hover {
    color: var(--accent-color);
    background: var(--bg-primary);
    border-color: var(--border-color);
}

.vuln-detail-field__copy-spacer {
    flex-shrink: 0;
    width: 26px;
    height: 26px;
    margin-top: 2px;
}

.vulnerability-repro {
    display: flex;
    flex-direction: column;
    gap: 12px;
}

.vulnerability-section,
.vulnerability-proof,
.vulnerability-impact,
.vulnerability-recommendation {
    margin-top: 12px;
    padding: 12px;
    background: var(--bg-secondary);
    border-radius: 6px;
    font-size: 0.875rem;
    line-height: 1.6;
}

.vulnerability-section:first-child {
    margin-top: 0;
}

.vulnerability-proof pre {
    margin-top: 8px;
    padding: 12px;
    background: var(--bg-primary);
    border: 1px solid var(--border-color);
    border-radius: 4px;
    overflow-x: auto;
    font-size: 0.8rem;
    font-family: 'Monaco', 'Menlo', 'Ubuntu Mono', monospace;
    white-space: pre-wrap;
    word-wrap: break-word;
}

.vulnerability-section-body {
    margin-top: 8px;
    color: var(--text-primary);
    white-space: pre-wrap;
    overflow-wrap: anywhere;
}

.vulnerability-section-body--code {
    margin-top: 8px;
    padding: 12px;
    background: var(--bg-primary);
    border: 1px solid var(--border-color);
    border-radius: 4px;
    overflow-x: auto;
    font-size: 0.8rem;
    font-family: 'Monaco', 'Menlo', 'Ubuntu Mono', monospace;
    white-space: pre-wrap;
    word-wrap: break-word;
}

.vulnerability-section strong,
.vulnerability-proof strong,
.vulnerability-impact strong,
.vulnerability-recommendation strong {
    color: var(--text-primary);
    display: block;
    margin-bottom: 8px;
}

.empty-state {
    text-align: center;
    padding: 48px;
    color: var(--text-secondary);
    font-size: 1rem;
}

