/* 角色选择器包装器 */
.role-selector-wrapper {
    position: relative;
    flex-shrink: 0;
}

.agent-mode-wrapper {
    display: flex;
    align-items: center;
    flex-shrink: 0;
}

/* 与角色选择器共用 .role-selector-btn；此处仅包一层用于定位浮层 */
.agent-mode-inner {
    position: relative;
    flex-shrink: 0;
}

/* 单/多代理面板：与「选择角色」浮层同一视觉语言（白底、圆角、阴影） */
.agent-mode-panel {
    position: absolute;
    bottom: calc(100% + 8px);
    left: 0;
    width: 300px;
    max-width: calc(100vw - 32px);
    background: #ffffff;
    border: 1px solid rgba(0, 0, 0, 0.08);
    border-radius: 16px;
    padding: 12px;
    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.12), 0 4px 16px rgba(0, 0, 0, 0.08), 0 0 0 1px rgba(0, 0, 0, 0.04);
    z-index: 1000;
    display: flex;
    flex-direction: column;
    animation: slideUp 0.25s cubic-bezier(0.16, 1, 0.3, 1);
    text-align: left;
}

.agent-mode-panel-header {
    margin-bottom: 8px;
    text-align: left;
}

.agent-mode-panel .role-selection-panel-title {
    text-align: left;
}

.agent-mode-options {
    display: flex;
    flex-direction: column;
    gap: 6px;
    min-height: 0;
    overflow: visible;
}

.agent-mode-options > .role-selection-item-main {
    flex-shrink: 0;
}

/* 选项为 <button>，浏览器默认 text-align:center 会继承到文案，强制左对齐与角色列表一致 */
.agent-mode-option.role-selection-item-main {
    text-align: left;
    justify-content: flex-start;
}

.agent-mode-option .role-selection-item-content-main,
.agent-mode-option .role-selection-item-name-main,
.agent-mode-option .role-selection-item-description-main {
    text-align: left;
}

.agent-mode-option::after {
    content: attr(data-agent-mode-detail);
    position: absolute;
    left: calc(100% + 12px);
    top: 50%;
    z-index: 20;
    width: max-content;
    max-width: min(380px, calc(100vw - 40px));
    padding: 9px 11px;
    border-radius: 8px;
    background: #ffffff;
    color: var(--text-primary);
    border: 1px solid rgba(0, 0, 0, 0.08);
    font-size: 0.75rem;
    line-height: 1.45;
    text-align: left;
    white-space: normal;
    overflow-wrap: anywhere;
    box-shadow: 0 8px 24px rgba(0, 0, 0, 0.12), 0 2px 8px rgba(0, 0, 0, 0.06);
    opacity: 0;
    visibility: hidden;
    transform: translate(4px, -50%);
    pointer-events: none;
    transition: opacity 0.16s ease, transform 0.16s ease, visibility 0.16s ease;
}

.agent-mode-option::before {
    content: "";
    position: absolute;
    left: calc(100% + 6px);
    top: 50%;
    z-index: 21;
    width: 10px;
    height: 10px;
    background: #ffffff;
    border-left: 1px solid rgba(0, 0, 0, 0.08);
    border-bottom: 1px solid rgba(0, 0, 0, 0.08);
    opacity: 0;
    visibility: hidden;
    transform: translate(4px, -50%) rotate(45deg);
    pointer-events: none;
    transition: opacity 0.16s ease, transform 0.16s ease, visibility 0.16s ease;
}

.agent-mode-option:hover::after,
.agent-mode-option:focus-visible::after,
.agent-mode-option:hover::before,
.agent-mode-option:focus-visible::before {
    opacity: 1;
    visibility: visible;
    transform: translate(0, -50%);
}

.agent-mode-option:hover::before,
.agent-mode-option:focus-visible::before {
    transform: translate(0, -50%) rotate(45deg);
}

/* 选项内勾选：未选中时隐藏（与角色列表一致） */
.agent-mode-option .agent-mode-check {
    display: none !important;
}

.agent-mode-option.selected .agent-mode-check {
    display: flex !important;
}

/* 主内容区域角色选择面板样式（下拉菜单形式） */
.role-selection-panel {
    position: absolute;
    bottom: calc(100% + 8px);
    left: 0;
    width: 340px;
    max-width: calc(100vw - 32px);
    max-height: min(580px, 60vh);
    background: #ffffff;
    border: 1px solid rgba(0, 0, 0, 0.08);
    border-radius: 16px;
    padding: 12px;
