}

.role-selection-item-main.selected .role-selection-item-description-main {
    color: #8a5ab8;
}

.selection-detail-tooltip {
    position: fixed;
    z-index: 10000;
    max-width: min(380px, calc(100vw - 40px));
    padding: 9px 11px;
    border-radius: 8px;
    background: #ffffff;
    color: var(--text-primary);
    border: 1px solid rgba(0, 0, 0, 0.08);
    font-size: 0.75rem;
    line-height: 1.45;
    text-align: left;
    white-space: normal;
    overflow-wrap: anywhere;
    box-shadow: 0 8px 24px rgba(0, 0, 0, 0.12), 0 2px 8px rgba(0, 0, 0, 0.06);
    opacity: 0;
    visibility: hidden;
    pointer-events: none;
    transform: translateX(4px);
    transition: opacity 0.16s ease, transform 0.16s ease, visibility 0.16s ease;
}

.selection-detail-tooltip.visible {
    opacity: 1;
    visibility: visible;
    transform: translateX(0);
}

.selection-detail-tooltip::before {
    content: "";
    position: absolute;
    left: -5px;
    top: 50%;
    width: 10px;
    height: 10px;
    background: #ffffff;
    border-left: 1px solid rgba(0, 0, 0, 0.08);
    border-bottom: 1px solid rgba(0, 0, 0, 0.08);
    transform: translateY(-50%) rotate(45deg);
}

.selection-detail-tooltip.placement-left {
    transform: translateX(-4px);
}

.selection-detail-tooltip.placement-left.visible {
    transform: translateX(0);
}

.selection-detail-tooltip.placement-left::before {
    left: auto;
    right: -5px;
    border-left: none;
    border-bottom: none;
    border-right: 1px solid rgba(0, 0, 0, 0.08);
    border-top: 1px solid rgba(0, 0, 0, 0.08);
}

.role-selection-checkmark-main {
    position: absolute;
    top: 10px;
    right: 10px;
    width: 20px;
    height: 20px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: linear-gradient(135deg, #8a2be2 0%, #6a1bb2 100%);
    color: white;
    border-radius: 50%;
    font-size: 0.6875rem;
    font-weight: 700;
    flex-shrink: 0;
    box-shadow: 0 2px 8px rgba(138, 43, 226, 0.4);
    animation: checkmarkPop 0.3s cubic-bezier(0.16, 1, 0.3, 1);
}

@keyframes checkmarkPop {
    0% {
        transform: scale(0);
        opacity: 0;
    }
    50% {
        transform: scale(1.1);
    }
    100% {
        transform: scale(1);
        opacity: 1;
    }
}

@keyframes highlight-flash {
    0%, 100% {
        background-color: transparent;
    }
    50% {
        background-color: rgba(138, 43, 226, 0.1);
    }
}

.role-select-item {
