    z-index: 10000;
    padding: 32px;
}

.info-collect-cell-modal-content {
    width: min(760px, 100%);
    max-height: min(78vh, 720px);
    background: var(--bg-primary);
    border: 1px solid var(--border-color);
    border-radius: 12px;
    box-shadow: 0 24px 70px rgba(0,0,0,0.35);
    display: flex;
    flex-direction: column;
    overflow: hidden;
}

.info-collect-cell-modal-header {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 16px;
    padding: 18px 20px 16px;
    border-bottom: 1px solid var(--border-color);
}

.info-collect-cell-modal-heading {
    min-width: 0;
}

.info-collect-cell-modal-title {
    font-weight: 600;
    color: var(--text-primary);
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    font-size: 1rem;
    line-height: 1.4;
}

.info-collect-cell-modal-subtitle {
    margin-top: 4px;
    color: var(--text-secondary);
    font-size: 0.8125rem;
    line-height: 1.4;
}

.info-collect-cell-modal-header .btn-icon {
    flex: 0 0 auto;
}

.info-collect-cell-modal-body {
    padding: 18px 20px;
    overflow: auto;
    min-height: 112px;
}

.info-collect-cell-modal-pre {
    margin: 0;
    min-height: 64px;
    padding: 14px 16px;
    border: 1px solid var(--border-color);
    border-radius: 8px;
    background: var(--bg-secondary);
    white-space: pre-wrap;
    word-break: break-word;
    font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;
    font-size: 0.875rem;
    line-height: 1.55;
    color: var(--text-primary);
    user-select: text;
}

.info-collect-cell-modal-footer {
    padding: 14px 20px 18px;
    border-top: 1px solid var(--border-color);
    display: flex;
    justify-content: flex-end;
    gap: 10px;
    background: var(--bg-primary);
}

@media (max-width: 640px) {
    .info-collect-cell-modal {
        align-items: flex-end;
        padding: 16px;
    }

    .info-collect-cell-modal-content {
        width: 100%;
        max-height: 82vh;
    }

    .info-collect-cell-modal-header {
        padding: 16px;
    }

    .info-collect-cell-modal-body {
        padding: 16px;
    }

    .info-collect-cell-modal-footer {
        padding: 12px 16px 16px;
    }
