.info-collect-parse-modal-body {
    padding: 18px 28px;
    overflow: auto;
}

.info-collect-parse-form-group {
    margin-top: 14px;
}

.info-collect-parse-nl-text {
    margin-top: 6px;
    white-space: pre-wrap;
}

.info-collect-parse-warnings {
    background: #fff8e1;
    border: 1px solid #ffe8a3;
    border-radius: 10px;
    padding: 10px 12px;
    color: #92400e;
    font-size: 0.875rem;
    line-height: 1.5;
}

.info-collect-parse-warnings-list {
    margin: 8px 0 0 18px;
}

.info-collect-parse-warnings-empty {
    margin-top: 8px;
}

.info-collect-parse-explanation {
    margin-top: 8px;
    white-space: pre-wrap;
    background: var(--bg-tertiary);
    border: 1px solid var(--border-color);
    border-radius: 10px;
    padding: 10px 12px;
    font-size: 13px;
    color: var(--text-primary);
}

.info-collect-parse-modal-footer {
    padding: 18px 28px;
