    border-color: var(--accent-color);
    box-shadow: 0 0 0 2px rgba(0, 102, 255, 0.1);
}
.chat-project-panel-search-input::placeholder {
    color: var(--text-muted);
}
.chat-project-panel-hint {
    padding: 10px 4px 4px;
    font-size: 0.75rem;
    color: var(--text-muted);
    text-align: center;
    line-height: 1.4;
}
.chat-project-panel .role-selection-list-main {
    flex: 1;
    min-height: 0;
    max-height: min(360px, 50vh);
    padding-right: 0;
    margin: 0;
    width: 100%;
    overflow-x: hidden;
}
.chat-project-panel .role-selection-item-main {
    width: 100%;
    min-width: 0;
}
.chat-project-panel-loading,
.chat-project-panel-empty {
    padding: 16px 0;
    font-size: 0.8125rem;
    color: #64748b;
    text-align: center;
}
.chat-project-panel-footer {
    flex-shrink: 0;
    margin-top: 6px;
    padding-top: 10px;
    border-top: 1px solid rgba(0, 0, 0, 0.06);
    width: 100%;
}
.chat-project-panel .role-selection-item-main.chat-project-panel-create-btn {
    display: flex;
    flex-direction: row;
    align-items: center;
    justify-content: center;
    gap: 8px;
    width: 100%;
    min-width: 0;
    padding: 12px;
    border: 1.5px dashed rgba(99, 102, 241, 0.45);
    border-radius: 12px;
    background: rgba(99, 102, 241, 0.06);
    color: #4f46e5;
    font-size: 0.8125rem;
    font-weight: 600;
    box-shadow: none;
    transform: none;
}
.chat-project-panel .role-selection-item-main.chat-project-panel-create-btn:hover,
.chat-project-panel .role-selection-item-main.chat-project-panel-create-btn:focus-visible,
.chat-project-panel .role-selection-item-main.chat-project-panel-create-btn:active {
    background: rgba(99, 102, 241, 0.12);
    border-color: rgba(99, 102, 241, 0.65);
    color: #4338ca;
    box-shadow: none;
    transform: none;
}
.chat-project-panel-create-icon {
    flex-shrink: 0;
    font-size: 1.125rem;
    line-height: 1;
    font-weight: 500;
}
.chat-project-panel-create-label {
    line-height: 1.4;
}
@media (max-width: 900px) {
    #page-projects .page-content.projects-page-layout {
        flex-direction: column;
    }
    .projects-sidebar-card {
        width: 100%;
        max-height: 220px;
