.role-form-native-select {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border: 0;
}

#role-modal .role-form-select-ui {
    position: relative;
    width: 100%;
    min-width: 0;
}

#role-modal .role-form-select-trigger {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 8px;
    width: 100%;
    min-width: 0;
    min-height: 40px;
    padding: 10px 12px;
    border: 1px solid var(--border-color);
    border-radius: 8px;
    background: var(--bg-primary);
    color: var(--text-primary);
    font-size: 0.875rem;
    line-height: 1.25;
    cursor: pointer;
    font-family: inherit;
    transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

#role-modal .role-form-select-trigger:hover:not(:disabled) {
    border-color: rgba(59, 130, 246, 0.45);
}

#role-modal .role-form-select-ui.open .role-form-select-trigger {
    border-color: var(--accent-color);
    box-shadow: 0 0 0 2px rgba(59, 130, 246, 0.12);
}

#role-modal .role-form-select-ui.open {
    z-index: 120;
}

#role-modal .role-form-select-ui.is-disabled .role-form-select-trigger {
    opacity: 0.6;
    cursor: not-allowed;
}

#role-modal .role-form-select-value {
    flex: 1;
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    text-align: left;
}

#role-modal .role-form-select-caret {
    flex-shrink: 0;
    color: var(--text-secondary);
    transition: transform 0.15s ease;
}

#role-modal .role-form-select-ui.open .role-form-select-caret {
    transform: rotate(180deg);
}

#role-modal .role-form-select-dropdown {
    display: none;
    position: absolute;
    top: calc(100% + 4px);
    left: 0;
    right: 0;
    z-index: 200;
    max-height: 280px;
    overflow-y: auto;
    padding: 4px;
    background: var(--bg-primary);
    border: 1px solid var(--border-color);
    border-radius: 8px;
    box-shadow: var(--shadow-lg);
}

#role-modal .role-form-select-ui.open .role-form-select-dropdown {
    display: block;
}

#role-modal .role-form-select-option {
    display: flex;
    align-items: center;
    gap: 8px;
    width: 100%;
    padding: 8px 10px;
    border: none;
    border-radius: 6px;
    background: transparent;
    color: var(--text-primary);
    font-size: 0.8125rem;
    font-family: inherit;
    cursor: pointer;
    text-align: left;
    transition: background 0.12s ease, color 0.12s ease;
}

#role-modal .role-form-select-option:hover {
    background: var(--bg-secondary);
}

#role-modal .role-form-select-option.is-selected {
    background: rgba(59, 130, 246, 0.08);
    color: #2563eb;
    font-weight: 500;
}

#role-modal .role-form-select-check {
    width: 14px;
    flex-shrink: 0;
    visibility: hidden;
    color: #2563eb;
    font-size: 12px;
    line-height: 1;
}

#role-modal .role-form-select-option.is-selected .role-form-select-check {
    visibility: visible;
}

#role-modal .role-form-select-label {
    flex: 1;
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

