/* Workflow drag editor */
.workflow-page-content {
    display: grid;
    grid-template-columns:
        clamp(200px, 16vw, 260px)
        minmax(0, 1fr)
        clamp(220px, 20vw, 300px);
    gap: 14px;
    min-height: calc(100vh - 150px);
    width: 100%;
    max-width: 100%;
    box-sizing: border-box;
}

.workflow-sidebar,
.workflow-properties,
.workflow-main {
    min-width: 0;
    max-width: 100%;
    overflow: hidden;
}

.workflow-panel,
.workflow-properties,
.workflow-meta-bar,
.workflow-canvas-wrap {
    border: 1px solid var(--border-color);
    background: var(--bg-secondary);
    border-radius: 8px;
}

.workflow-panel {
    margin-bottom: 14px;
    overflow: hidden;
}

.workflow-panel-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 12px 14px;
    border-bottom: 1px solid var(--border-color);
}

.workflow-panel-header h3 {
    margin: 0;
    font-size: 14px;
    font-weight: 700;
}

.workflow-list {
    display: grid;
    gap: 8px;
    padding: 12px;
    max-height: 330px;
    overflow: auto;
}

.workflow-list-item {
    display: flex;
    align-items: center;
    gap: 10px;
    width: 100%;
    min-height: 62px;
    padding: 10px 10px 10px 13px;
    border: 1px solid var(--border-color);
    border-radius: 10px;
    background: var(--bg-primary);
    color: var(--text-primary);
    box-sizing: border-box;
    transition: border-color 0.18s ease, box-shadow 0.18s ease, background 0.18s ease, transform 0.18s ease;
}

.workflow-list-item.is-active {
    border-color: var(--accent-color);
    background: rgba(59, 130, 246, 0.08);
    box-shadow: inset 3px 0 0 var(--accent-color);
}

.workflow-list-item:hover {
    border-color: rgba(59, 130, 246, 0.45);
    background: rgba(59, 130, 246, 0.05);
    transform: translateY(-1px);
}

.workflow-list-main {
    flex: 1;
    min-width: 0;
    display: grid;
    gap: 3px;
    text-align: left;
    padding: 2px 0;
    border: none;
    background: transparent;
    color: inherit;
    cursor: pointer;
}

.workflow-list-actions {
    display: flex;
    align-items: center;
    gap: 3px;
    flex-shrink: 0;
}

.workflow-list-edit {
    width: 26px;
    height: 26px;
    padding: 0;
    border: 0;
    border-radius: 50%;
    background: transparent;
    color: var(--text-secondary);
    opacity: 0.62;
    transition: color 0.16s ease, background 0.16s ease, opacity 0.16s ease, transform 0.16s ease;
}

.workflow-list-item:hover .workflow-list-edit,
.workflow-list-edit:focus-visible {
    opacity: 1;
}

.workflow-list-edit:hover {
    color: var(--accent-color);
    background: rgba(59, 130, 246, 0.10);
    transform: scale(1.04);
}

.workflow-status-toggle {
    display: inline-flex;
    align-items: center;
    gap: 5px;
    min-height: 24px;
    padding: 3px 7px;
    border: 1px solid transparent;
    border-radius: 999px;
    font: inherit;
    font-size: 10px;
    line-height: 1;
    font-weight: 650;
    white-space: nowrap;
    cursor: pointer;
    transition: color 0.16s ease, border-color 0.16s ease, background 0.16s ease, box-shadow 0.16s ease;
}

.workflow-status-toggle.is-enabled {
    color: #15803d;
    border-color: rgba(34, 197, 94, 0.22);
    background: rgba(34, 197, 94, 0.09);
}

.workflow-status-toggle.is-disabled {
    color: var(--text-secondary);
    border-color: var(--border-color);
    background: var(--bg-secondary);
}

.workflow-status-toggle:hover {
    box-shadow: 0 0 0 2px rgba(59, 130, 246, 0.08);
}

.workflow-status-toggle:focus-visible,
.workflow-list-edit:focus-visible {
    outline: 2px solid rgba(59, 130, 246, 0.38);
    outline-offset: 2px;
}

.workflow-status-dot {
    width: 6px;
    height: 6px;
    flex: 0 0 auto;
    border-radius: 50%;
    background: currentColor;
    box-shadow: 0 0 0 2px rgba(100, 116, 139, 0.10);
}

.workflow-status-toggle.is-enabled .workflow-status-dot {
    box-shadow: 0 0 0 2px rgba(34, 197, 94, 0.14);
}

html[data-theme="dark"] .workflow-status-toggle.is-enabled {
    color: #86efac;
    border-color: rgba(74, 222, 128, 0.20);
    background: rgba(34, 197, 94, 0.10);
}

html[data-theme="dark"] .workflow-status-toggle.is-disabled {
    color: #94a3b8;
    border-color: rgba(148, 163, 184, 0.16);
    background: rgba(148, 163, 184, 0.07);
}

.workflow-switch {
    position: relative;
    display: inline-flex;
    width: 34px;
    height: 20px;
    flex-shrink: 0;
}

.workflow-switch input {
    opacity: 0;
    width: 0;
    height: 0;
    position: absolute;
}

.workflow-switch-slider {
    position: absolute;
    inset: 0;
    background: rgba(100, 116, 139, 0.35);
    border-radius: 999px;
    transition: background 0.2s ease;
    cursor: pointer;
}

.workflow-switch-slider::before {
    content: '';
    position: absolute;
    width: 14px;
    height: 14px;
    left: 3px;
    top: 3px;
    background: #fff;
    border-radius: 50%;
    box-shadow: 0 1px 2px rgba(15, 23, 42, 0.18);
    transition: transform 0.2s ease;
}

.workflow-switch input:checked + .workflow-switch-slider {
    background: var(--accent-color);
}

.workflow-switch input:checked + .workflow-switch-slider::before {
    transform: translateX(14px);
}

.workflow-switch input:focus-visible + .workflow-switch-slider {
    outline: 2px solid rgba(59, 130, 246, 0.45);
    outline-offset: 2px;
}

.workflow-switch--modal {
    width: 42px;
    height: 24px;
}

.workflow-switch--modal .workflow-switch-slider::before {
    width: 18px;
    height: 18px;
    top: 3px;
    left: 3px;
}

.workflow-switch--modal input:checked + .workflow-switch-slider::before {
    transform: translateX(18px);
}

.workflow-list-title {
    font-weight: 700;
    font-size: 13px;
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.workflow-list-meta {
    color: var(--text-secondary);
    font-size: 11px;
    line-height: 1.3;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.workflow-node-palette {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 8px;
    padding: 12px;
}

.workflow-node-palette button {
    padding: 10px;
    border: 1px dashed var(--border-color);
    border-radius: 8px;
    background: var(--bg-primary);
    color: var(--text-primary);
    cursor: grab;
}

.workflow-node-palette button:active {
    cursor: grabbing;
}

.workflow-main {
    display: grid;
    grid-template-rows: auto minmax(520px, 1fr);
    gap: 14px;
    min-width: 0;
}

.workflow-meta-bar {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    align-items: center;
    gap: 0;
    padding: 8px 10px 8px 12px;
    min-height: 44px;
    box-sizing: border-box;
    background: var(--bg-primary);
    box-shadow: inset 0 -1px 0 rgba(15, 23, 42, 0.06);
}

.workflow-canvas-header {
    min-width: 0;
    padding-right: 12px;
}

.workflow-canvas-heading {
    display: flex;
    align-items: center;
    gap: 8px;
    min-width: 0;
    max-width: 100%;
    padding: 5px 12px;
    min-height: 32px;
    box-sizing: border-box;
    border-radius: 7px;
    background: var(--bg-secondary);
    border: 1px solid var(--border-color);
    overflow: hidden;
}

.workflow-canvas-title {
    margin: 0;
    font-size: 15px;
    font-weight: 700;
    color: var(--text-primary);
    line-height: 1.3;
    flex-shrink: 0;
    max-width: 40%;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.workflow-canvas-subtitle {
    font-size: 12px;
    color: var(--text-secondary);
    line-height: 1.3;
    min-width: 0;
    flex: 1;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.workflow-canvas-subtitle::before {
    content: '·';
    margin-right: 8px;
    opacity: 0.45;
}

.workflow-canvas-title.is-disabled {
    opacity: 0.7;
}

.workflow-meta-modal-content {
    max-width: 340px;
    width: calc(100vw - 32px);
    margin: 12vh auto auto;
    height: auto !important;
    max-height: none !important;
}

.workflow-meta-modal-content .modal-header.workflow-meta-modal-header {
    padding: 8px 12px !important;
    min-height: 0;
    box-shadow: none;
}

.workflow-meta-modal-content .modal-header.workflow-meta-modal-header h2 {
    font-size: 13px;
    font-weight: 700;
    line-height: 1.2;
}

.workflow-meta-modal-content .modal-body.workflow-meta-modal-body {
    display: grid;
    gap: 6px;
    padding: 8px 12px !important;
    flex: 0 0 auto !important;
    overflow: visible;
