}

.workflow-tool-select-dropdown {
    display: none;
    position: absolute;
    top: calc(100% + 4px);
    left: 0;
    right: 0;
    z-index: 300;
    max-height: 280px;
    overflow: hidden;
    padding: 0;
    background: var(--bg-primary);
    border: 1px solid var(--border-color);
    border-radius: 8px;
    box-shadow: var(--shadow-lg);
    flex-direction: column;
}

.workflow-tool-select.open .workflow-tool-select-dropdown {
    display: flex;
}

.workflow-tool-select-search {
    flex-shrink: 0;
    padding: 8px;
    border-bottom: 1px solid var(--border-color);
    background: var(--bg-primary);
}

.workflow-tool-select-search-input {
    width: 100%;
    padding: 6px 10px;
    border: 1px solid var(--border-color);
    border-radius: 6px;
    font-size: 0.8125rem;
    background: var(--bg-primary);
    color: var(--text-primary);
    font-family: inherit;
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

.workflow-tool-select-search-input:focus {
    outline: none;
    border-color: var(--accent-color);
    box-shadow: 0 0 0 2px rgba(0, 102, 255, 0.1);
}

.workflow-tool-select-search-input::placeholder {
    color: var(--text-muted);
}

.workflow-tool-select-options {
    flex: 1;
    min-height: 0;
    overflow-x: hidden;
    overflow-y: auto;
    padding: 4px;
}

.workflow-tool-select-option {
    display: flex;
    align-items: center;
    gap: 8px;
    width: 100%;
    min-width: 0;
    padding: 8px 10px;
    border: none;
    border-radius: 6px;
    background: transparent;
    color: var(--text-primary);
    font-size: 0.8125rem;
    font-family: inherit;
    cursor: pointer;
    text-align: left;
}

.workflow-tool-select-option:hover {
    background: var(--bg-secondary);
}

.workflow-tool-select-option.is-selected {
    color: var(--accent-color);
    font-weight: 600;
    background: rgba(0, 102, 255, 0.08);
}

.workflow-tool-select-check {
    flex: 0 0 14px;
    width: 14px;
    color: var(--accent-color);
    opacity: 0;
    font-size: 0.75rem;
    line-height: 1;
}

.workflow-tool-select-option.is-selected .workflow-tool-select-check {
    opacity: 1;
}

.workflow-tool-select-label {
    flex: 1;
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.workflow-tool-select-empty {
    padding: 10px 12px;
    text-align: center;
    color: var(--text-muted);
    font-size: 0.8125rem;
    line-height: 1.4;
}

@media (max-width: 1400px) {
    .workflow-page-content {
        grid-template-columns: clamp(180px, 14vw, 220px) minmax(0, 1fr);
    }

    .workflow-properties {
        grid-column: 1 / -1;
        grid-row: 2;
        max-height: min(42vh, 420px);
    }

    .workflow-sidebar {
        grid-row: 1;
    }

    .workflow-main {
        grid-row: 1;
    }
}

@media (max-width: 900px) {
    .workflow-page-content {
        grid-template-columns: minmax(0, 1fr);
    }

    .workflow-sidebar {
        grid-column: 1 / -1;
    }

    .workflow-main {
        grid-column: 1 / -1;
    }
}

/* Platform RBAC */
.platform-rbac-page .page-content {
    overflow: hidden;
}

.platform-rbac-page .page-header { align-items: center; }
.rbac-page-subtitle { margin: 5px 0 0; color: var(--text-secondary); font-size: 0.8125rem; }

.rbac-overview {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 12px;
    margin-bottom: 14px;
}

.rbac-metric {
    min-width: 0;
    padding: 12px 14px;
    border: 1px solid var(--border-color);
    border-radius: 8px;
    background: var(--bg-primary);
}

.rbac-metric span {
    display: block;
    color: var(--text-secondary);
    font-size: 0.75rem;
    line-height: 1.2;
}

.rbac-metric strong {
    display: block;
    margin-top: 6px;
    color: var(--text-primary);
    font-size: 1.375rem;
    line-height: 1;
}

.rbac-layout {
    display: grid;
    grid-template-columns: minmax(280px, 328px) minmax(0, 1fr);
    gap: 16px;
    align-items: stretch;
    height: 100%;
    min-height: 0;
    overflow: hidden;
}

.rbac-panel {
    min-width: 0;
    min-height: 0;
    border: 1px solid var(--border-color);
    border-radius: 8px;
    background: var(--bg-primary);
    display: flex;
    flex-direction: column;
}

.rbac-panel-head,
.rbac-detail-head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    padding: 14px 16px;
    border-bottom: 1px solid var(--border-color);
}

.rbac-panel-head h3,
.rbac-detail-head h3 {
    margin: 0;
    font-size: 1rem;
}

.rbac-muted {
    margin: 4px 0 0;
    color: var(--text-secondary);
    font-size: 0.8125rem;
}

.rbac-count,
.rbac-pill {
    display: inline-flex;
    align-items: center;
    min-height: 22px;
    padding: 2px 8px;
    border: 1px solid var(--border-color);
    border-radius: 999px;
    color: var(--text-secondary);
    font-size: 0.75rem;
    line-height: 1.2;
    white-space: nowrap;
}

.rbac-pill.is-ok {
    color: #166534;
    border-color: rgba(22, 101, 52, 0.24);
    background: rgba(22, 101, 52, 0.08);
}

.rbac-pill.is-muted {
    color: var(--text-muted);
}

.rbac-list,
.rbac-tab-panel {
    min-height: 0;
    overflow: auto;
    padding: 12px;
}

.rbac-search {
    padding: 12px 14px 0;
}

.rbac-search .form-input {
    width: 100%;
    min-height: 36px;
    border-radius: 8px;
}

.rbac-user-row {
    width: 100%;
    border: 1px solid transparent;
    border-radius: 8px;
    background: transparent;
    color: var(--text-primary);
    text-align: left;
    cursor: pointer;
}

.rbac-user-row:hover,
.rbac-user-row.is-active {
    border-color: rgba(37, 99, 235, 0.28);
    background: rgba(37, 99, 235, 0.05);
}

.rbac-detail-actions {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
}

.rbac-selected-summary {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 10px;
    padding: 12px 16px;
    border-bottom: 1px solid var(--border-color);
    background: var(--bg-secondary);
}

.rbac-selected-summary:empty {
    display: none;
}

.rbac-selected-summary div {
    min-width: 0;
}

.rbac-selected-summary span {
    display: block;
    color: var(--text-secondary);
    font-size: 0.71875rem;
}

.rbac-selected-summary strong {
    display: block;
    margin-top: 3px;
    color: var(--text-primary);
    font-size: 0.9375rem;
}

.rbac-tabs {
    display: flex;
    gap: 6px;
    padding: 10px 12px 0;
}

.rbac-tab {
    border: 1px solid var(--border-color);
    border-radius: 8px 8px 0 0;
    background: var(--bg-secondary);
    color: var(--text-secondary);
    padding: 8px 12px;
    cursor: pointer;
}

.rbac-tab.is-active {
    background: var(--bg-primary);
    color: var(--text-primary);
    border-bottom-color: var(--bg-primary);
}

.rbac-section-toolbar {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 12px;
    margin-bottom: 12px;
}

.rbac-section-toolbar strong {
    display: block;
    font-size: 0.9375rem;
}

.rbac-role-save-actions {
    display: flex;
    align-items: center;
    gap: 7px;
}

.rbac-unsaved-indicator {
    color: #9a3412;
    font-size: 0.75rem;
}

.rbac-unsaved-indicator[hidden] { display: none !important; }

.rbac-role-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
    gap: 12px;
}

.rbac-role-card {
    border: 1px solid var(--border-color);
    border-radius: 8px;
    padding: 12px;
    background: var(--bg-primary);
    transition: border-color 0.15s, box-shadow 0.15s;
}

.rbac-role-card:hover {
    border-color: rgba(37, 99, 235, 0.26);
    box-shadow: 0 8px 18px rgba(15, 23, 42, 0.06);
}

.rbac-role-card-head,
.rbac-role-card-foot,
.rbac-assignment-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 10px;
}

.rbac-role-card p {
    min-height: 36px;
    margin: 10px 0;
    color: var(--text-secondary);
    font-size: 0.8125rem;
    line-height: 1.45;
}

.rbac-role-card-foot {
    color: var(--text-secondary);
    font-size: 0.8125rem;
    justify-content: flex-start;
    flex-wrap: wrap;
}

.rbac-assignment-toolbar {
    margin-bottom: 0;
}

.rbac-assignment-field {
    display: flex;
    flex-direction: column;
    gap: 5px;
    min-width: 160px;
}

.rbac-assignment-field label {
    color: var(--text-secondary);
    font-size: 0.75rem;
    font-weight: 600;
}

.rbac-assignment-field--id {
    flex: 1;
    min-width: 280px;
}

.rbac-assignment-toolbar .btn-primary {
    align-self: end;
}

.rbac-assignments-list {
    display: flex;
    flex-direction: column;
    gap: 8px;
}

.rbac-resource-picker {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
    gap: 8px;
    max-height: 260px;
    margin-bottom: 12px;
    overflow: auto;
}

.rbac-resource-option {
    display: flex;
    align-items: center;
    gap: 9px;
    min-width: 0;
    padding: 10px;
    border: 1px solid var(--border-color);
    border-radius: 8px;
    background: var(--bg-primary);
    cursor: pointer;
}

.rbac-resource-option:hover {
    border-color: rgba(37, 99, 235, 0.32);
    background: rgba(37, 99, 235, 0.035);
}

.rbac-resource-option:has(input:checked) {
    border-color: rgba(37, 99, 235, 0.45);
    background: rgba(37, 99, 235, 0.06);
}

.rbac-resource-option.is-assigned {
    cursor: default;
    opacity: 0.7;
}

.rbac-resource-option-main {
    flex: 1;
    min-width: 0;
}

.rbac-resource-option-main strong,
.rbac-resource-option-main small {
    display: block;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.rbac-resource-option-main strong {
    color: var(--text-primary);
    font-size: 0.8125rem;
}

.rbac-resource-option-main small,
.rbac-resource-option-detail {
    margin-top: 3px;
    color: var(--text-secondary);
    font-size: 0.6875rem;
}

.rbac-resource-option-detail {
    flex-shrink: 0;
    max-width: 90px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.rbac-picker-status {
    grid-column: 1 / -1;
    padding: 28px 16px;
    border: 1px dashed var(--border-color);
    border-radius: 8px;
    color: var(--text-secondary);
    font-size: 0.8125rem;
    text-align: center;
}

.rbac-picker-status.is-error { color: var(--danger-color, #dc2626); }
.rbac-button-count {
    min-width: 18px;
    margin-left: 5px;
    padding: 1px 5px;
    border-radius: 999px;
    background: rgba(255, 255, 255, 0.2);
    font-size: 0.6875rem;
}

.rbac-assignment-list-head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin: 4px 0 9px;
    color: var(--text-primary);
    font-size: 0.8125rem;
}

.rbac-assignment-list-head span {
    color: var(--text-secondary);
    font-size: 0.75rem;
}

.rbac-assignment-row {
    border: 1px solid var(--border-color);
    border-radius: 8px;
    padding: 10px 12px;
    background: var(--bg-primary);
}

.rbac-resource-selection-bar {
    display: none !important;
}

.rbac-metric-context {
    display: inline-flex;
    flex: 1 1 160px;
    align-items: center;
    gap: 7px;
    min-width: 0;
    max-width: min(25%, 360px);
    min-height: 36px;
    margin: 0;
    padding: 5px 7px 5px 10px;
    border: 1px solid var(--border-color);
    border-radius: 999px;
    background: var(--bg-primary);
    color: var(--text-secondary);
    font-size: 0.75rem;
    white-space: nowrap;
    overflow: hidden;
}

.rbac-metric-context[hidden] {
    display: none !important;
}

.rbac-context-label {
    flex: 0 0 auto;
    color: var(--text-muted);
}

.rbac-context-member {
    flex: 1 1 auto;
    min-width: 0;
    overflow: hidden;
    color: var(--text-primary);
    font-size: 0.8125rem;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.rbac-context-stat {
    display: inline-flex;
    flex: 0 0 auto;
    align-items: baseline;
    gap: 3px;
    padding: 3px 7px;
    border-radius: 999px;
    background: var(--bg-secondary);
}

.rbac-context-stat b {
    color: var(--accent-color);
    font-size: 0.8125rem;
}

.rbac-metric-enabled[hidden] {
    display: none !important;
}

.rbac-summary-permissions {
    position: relative;
}

.rbac-summary-count {
    display: block;
    margin-top: 3px;
    color: var(--text-primary);
    font-size: 0.9375rem;
    font-weight: 700;
    line-height: 1.2;
}

.rbac-summary-count--interactive {
    display: inline-flex;
    align-items: center;
    margin-top: 3px;
    padding: 0 0 1px;
    border: none;
    border-bottom: 1px dashed color-mix(in srgb, var(--text-secondary) 55%, transparent);
    border-radius: 0;
    background: none;
    color: var(--text-secondary);
    font-size: 0.9375rem;
    font-weight: 700;
    line-height: 1.2;
    cursor: pointer;
    transition: color 0.15s ease, border-color 0.15s ease;
}

.rbac-summary-count--interactive:hover {
    color: var(--text-primary);
    border-bottom-color: color-mix(in srgb, var(--text-secondary) 80%, transparent);
}

.rbac-summary-count--interactive[aria-expanded="true"] {
    color: var(--text-primary);
    border-bottom-color: var(--text-secondary);
    border-bottom-style: solid;
}

.rbac-summary-count--interactive:focus-visible {
    outline: 2px solid color-mix(in srgb, var(--text-secondary) 35%, transparent);
    outline-offset: 3px;
}

.rbac-permissions-popover {
    position: fixed;
    z-index: 220;
    width: min(380px, calc(100vw - 32px));
}

.rbac-permissions-popover[hidden] {
    display: none !important;
}

.rbac-permissions-popover-inner {
    position: relative;
    overflow: hidden;
    border: 1px solid var(--border-color);
    border-radius: 10px;
    background: var(--bg-primary);
    box-shadow: var(--shadow-md, 0 8px 24px rgba(15, 23, 42, 0.12));
}

.rbac-permissions-popover-inner::before {
    content: '';
    position: absolute;
    top: -5px;
    left: var(--rbac-popover-arrow-left, 18px);
    width: 10px;
    height: 10px;
    background: var(--bg-primary);
    border-left: 1px solid var(--border-color);
    border-top: 1px solid var(--border-color);
    transform: rotate(45deg);
}

.rbac-permissions-popover-count {
    color: var(--text-muted);
    font-size: 0.75rem;
    font-weight: 500;
}

.rbac-permissions-popover .rbac-effective-permissions-body {
    max-height: min(320px, calc(100vh - 180px));
}

.rbac-effective-permissions-head,
.rbac-effective-module h4 {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 8px;
}

.rbac-effective-permissions-head {
    padding: 10px 12px;
    border-bottom: 1px solid var(--border-color);
}

.rbac-effective-permissions-body {
    display: flex;
    flex-direction: column;
    gap: 10px;
    max-height: 240px;
    padding: 10px 12px 12px;
    overflow-y: auto;
}

.rbac-effective-module h4 {
    margin: 0 0 6px;
    font-size: 0.8125rem;
}

.rbac-effective-module h4 span {
    color: var(--text-muted);
    font-size: 0.75rem;
    font-weight: 500;
}

.rbac-effective-permission-tags {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
}

.rbac-effective-permission-tags span {
    padding: 3px 8px;
    border: 1px solid var(--border-color);
    border-radius: 999px;
    background: var(--bg-secondary);
    color: var(--text-secondary);
    font-size: 0.6875rem;
}

.rbac-audit-list {
    display: flex;
    flex: 1 1 auto;
    flex-direction: column;
    gap: 0;
    min-height: 0;
    overflow: hidden;
    overscroll-behavior: contain;
}

.rbac-panel-detail #rbac-tab-audit.rbac-tab-panel:not([hidden]) {
    container-name: rbac-audit;
    container-type: inline-size;
    display: flex;
    flex-direction: column;
    min-height: 0;
    overflow: hidden;
}

#rbac-tab-audit .rbac-audit-toolbar,
#rbac-tab-audit .rbac-pagination {
    flex: 0 0 auto;
}

.rbac-audit-table {
    display: flex;
    flex: 1 1 auto;
    flex-direction: column;
    width: 100%;
    min-width: 0;
    min-height: 0;
}

.rbac-audit-table-body {
    flex: 1 1 auto;
    min-height: 0;
    overflow-y: auto;
    overflow-x: hidden;
    overscroll-behavior: contain;
    scrollbar-width: thin;
    scrollbar-color: color-mix(in srgb, var(--text-muted) 60%, transparent) transparent;
}

.rbac-audit-table-body::-webkit-scrollbar {
    width: 6px;
}

.rbac-audit-table-body::-webkit-scrollbar-thumb {
    border-radius: 999px;
    background: color-mix(in srgb, var(--text-muted) 52%, transparent);
}

.rbac-audit-toolbar {
    display: grid;
    grid-template-columns: minmax(220px, 1fr) auto;
    align-items: end;
    gap: 20px;
    margin-bottom: 12px;
    padding: 10px 12px;
    border: 1px solid var(--border-color);
    border-radius: 8px;
    background: color-mix(in srgb, var(--bg-secondary) 72%, var(--bg-primary));
}

.rbac-audit-heading {
    min-width: 0;
    padding-bottom: 2px;
}

.rbac-audit-heading strong {
    display: block;
}

.rbac-audit-heading .rbac-muted {
    margin-top: 4px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.rbac-audit-filterbar {
    display: grid;
    grid-template-columns: 200px 220px;
    justify-content: end;
    gap: 10px;
    min-width: 0;
}

.rbac-audit-filter {
    display: flex;
    flex-direction: column;
    gap: 6px;
    min-width: 0;
}

.rbac-audit-filter > span {
    color: var(--text-secondary);
    font-size: 0.71875rem;
    font-weight: 600;
}

.rbac-audit-filter .settings-custom-select,
.rbac-audit-filter .form-select,
.rbac-audit-filter .form-input {
    width: 100%;
    min-width: 0;
}

.rbac-audit-filter .settings-custom-select-trigger,
.rbac-audit-filter .form-select,
.rbac-audit-filter .form-input {
    min-height: 38px;
    height: 38px;
}

.rbac-audit-pagination {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 16px;
    min-height: 54px;
    margin: 10px 0 0;
    padding: 8px 12px;
    border: 1px solid var(--border-color);
    border-radius: 10px;
}

.rbac-audit-pagination-meta,
.rbac-audit-pagination-nav,
.rbac-audit-page-size-control {
    display: flex;
    align-items: center;
}

.rbac-audit-pagination-meta {
    gap: 16px;
    min-width: 0;
    color: var(--text-secondary);
    font-size: 0.75rem;
}

.rbac-audit-page-size-control {
    gap: 8px;
    white-space: nowrap;
}

.rbac-audit-page-size-control .settings-custom-select,
.rbac-audit-page-size-control .form-select {
    width: 82px;
    min-width: 82px;
}

.rbac-audit-page-size-control .settings-custom-select-trigger,
.rbac-audit-page-size-control .form-select {
    min-height: 34px;
    height: 34px;
}

.rbac-audit-page-size-control .settings-custom-select-menu {
    top: auto;
    bottom: calc(100% + 6px);
}

.rbac-audit-pagination-nav {
    flex: 0 0 auto;
    justify-content: flex-end;
    gap: 8px;
}

.rbac-audit-pagination-nav > span {
    min-width: 76px;
    color: var(--text-secondary);
    font-size: 0.75rem;
    text-align: center;
    white-space: nowrap;
}

@container rbac-page (max-width: 900px) {
    .rbac-audit-pagination {
        align-items: stretch;
        flex-direction: column;
    }

    .rbac-audit-pagination-meta,
    .rbac-audit-pagination-nav {
        justify-content: space-between;
    }
}

.rbac-audit-table-head,
.rbac-audit-row {
    display: grid;
    grid-template-columns:
        minmax(130px, 0.85fr)
        minmax(90px, 0.55fr)
        minmax(80px, 0.5fr)
        minmax(320px, 2.1fr)
        minmax(180px, max-content);
    align-items: center;
    gap: 12px;
    width: 100%;
    min-width: 0;
    box-sizing: border-box;
}

.rbac-audit-table-head {
    padding: 9px 12px;
    border: 1px solid var(--border-color);
    border-bottom: 0;
    border-radius: 8px 8px 0 0;
    background: var(--bg-secondary);
    color: var(--text-secondary);
    font-size: 0.75rem;
    font-weight: 600;
}

.rbac-audit-row {
    padding: 8px 12px;
    border: 1px solid var(--border-color);
    border-bottom: 0;
    border-radius: 0;
    background: var(--bg-primary);
    font-size: 0.8125rem;
    line-height: 1.4;
}

.rbac-audit-row:last-child {
    border-bottom: 1px solid var(--border-color);
    border-radius: 0 0 8px 8px;
}

.rbac-audit-action {
    flex: 0 0 auto;
    font-weight: 600;
}

.rbac-audit-actor {
    justify-self: start;
}

.rbac-audit-cell-value {
    min-width: 0;
}

.rbac-audit-detail {
    flex: 0 1 auto;
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    color: var(--text-secondary);
    font-size: 0.75rem;
}

.rbac-audit-resource-id {
    overflow: visible;
    font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
    text-overflow: clip;
}

.rbac-audit-time {
    color: var(--text-secondary);
    font-size: 0.75rem;
    white-space: nowrap;
}

@container rbac-audit (max-width: 1000px) {
    .rbac-audit-table-head,
    .rbac-audit-row {
        grid-template-columns:
            minmax(110px, 0.82fr)
            minmax(72px, 0.5fr)
            minmax(62px, 0.42fr)
            minmax(230px, 1.9fr)
            minmax(145px, 0.95fr);
        gap: 8px;
        padding-right: 10px;
        padding-left: 10px;
    }

    .rbac-audit-resource-id {
        overflow-wrap: anywhere;
        white-space: normal;
    }
}

@container rbac-audit (max-width: 740px) {
    .rbac-audit-table-head {
        display: none;
    }

    .rbac-audit-table-body {
        display: flex;
        flex-direction: column;
        gap: 8px;
    }

    .rbac-audit-row,
    .rbac-audit-row:last-child {
        flex: 0 0 auto;
        grid-template-columns: repeat(2, minmax(0, 1fr));
        gap: 12px 16px;
        padding: 12px;
        border: 1px solid var(--border-color);
        border-radius: 8px;
    }

    .rbac-audit-row > [role="cell"] {
        display: grid;
        grid-template-columns: 68px minmax(0, 1fr);
        align-items: center;
        gap: 8px;
        min-width: 0;
        overflow: visible;
        white-space: normal;
    }

    .rbac-audit-row > [role="cell"]::before {
        content: attr(data-label);
        color: var(--text-muted);
        font-family: inherit;
        font-size: 0.6875rem;
        font-weight: 500;
        line-height: 1.2;
    }

    .rbac-audit-row .rbac-audit-actor {
        justify-self: stretch;
    }

    .rbac-audit-row .rbac-audit-resource-id {
        grid-column: 1 / -1;
        overflow-wrap: anywhere;
    }

    .rbac-audit-pagination {
        align-items: stretch;
        flex-direction: column;
    }

    .rbac-audit-pagination-meta,
    .rbac-audit-pagination-nav {
        justify-content: space-between;
    }
}

@container rbac-audit (max-width: 620px) {
    .rbac-audit-toolbar {
        grid-template-columns: minmax(0, 1fr);
        align-items: stretch;
        gap: 10px;
    }

    .rbac-audit-filterbar {
        grid-template-columns: repeat(2, minmax(0, 1fr));
        justify-content: stretch;
        width: 100%;
    }
}

@container rbac-audit (max-width: 520px) {
    .rbac-audit-filterbar {
        grid-template-columns: minmax(0, 1fr);
    }

    .rbac-audit-row,
    .rbac-audit-row:last-child {
        grid-template-columns: minmax(0, 1fr);
    }

    .rbac-audit-row .rbac-audit-resource-id {
        grid-column: auto;
    }

    .rbac-audit-pagination-meta,
    .rbac-audit-pagination-nav {
        flex-wrap: wrap;
        gap: 8px;
    }
}

.rbac-user-roles-readonly {
    display: flex;
    flex-direction: column;
    gap: 6px;
    margin-bottom: 8px;
}

.rbac-readonly-role {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 10px;
    padding: 8px 10px;
    border: 1px solid var(--border-color);
    border-radius: 8px;
    background: var(--bg-secondary);
}

.rbac-empty.is-compact {
    min-height: auto;
    padding: 12px;
}

.rbac-assignment-resource {
    display: flex;
    align-items: flex-start;
    gap: 10px;
    flex: 1;
    min-width: 0;
}

.rbac-assignment-row code {
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    color: var(--text-primary);
}

.rbac-checkbox-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
    gap: 8px;
}

.rbac-checkbox-item {
    padding: 8px;
    border: 1px solid var(--border-color);
    border-radius: 8px;
    background: var(--bg-primary);
}

.rbac-permission-groups {
    display: flex;
    flex-direction: column;
    gap: 14px;
    max-height: 48vh;
    overflow: auto;
    padding-right: 4px;
}

.rbac-permission-tools {
    display: grid;
    grid-template-columns: minmax(220px, 1fr) auto auto;
    gap: 8px;
    margin-bottom: 12px;
}

.rbac-permission-tools .form-input {
    min-height: 36px;
}

.rbac-permission-group {
    padding: 10px;
    border: 1px solid var(--border-color);
    border-radius: 8px;
    background: var(--bg-secondary);
}

.rbac-permission-group-head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 10px;
    margin-bottom: 8px;
}

.rbac-permission-group-head h4 {
    margin: 0;
    font-size: 0.875rem;
}

.rbac-permission-group-head h4 small {
    margin-left: 8px;
    color: var(--text-muted);
    font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
    font-size: 0.6875rem;
    font-weight: 500;
}

.rbac-permission-group-head span {
    color: var(--text-secondary);
    font-size: 0.75rem;
}

@media (max-width: 980px) {
    .rbac-overview {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .rbac-layout {
        grid-template-columns: minmax(0, 1fr);
        height: auto;
    }

    .rbac-selected-summary {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .rbac-permission-tools {
        grid-template-columns: minmax(0, 1fr);
    }
}

/* RBAC adaptive polish: one scroll surface, predictable controls and dense admin layouts. */
.platform-rbac-page,
.platform-rbac-page *,
#rbac-user-modal,
#rbac-user-modal *,
#rbac-role-modal,
#rbac-role-modal * {
    box-sizing: border-box;
}

.platform-rbac-page > .page-content {
    container-name: rbac-page;
    container-type: inline-size;
    overflow-x: hidden;
    overflow-y: auto;
    overscroll-behavior: contain;
    padding: 16px 20px 24px;
}

.platform-rbac-page > .page-header {
    position: relative;
    z-index: 2;
    gap: 16px;
    padding: 14px 20px;
}

.platform-rbac-page > .page-header > div:first-child {
    min-width: 0;
}

.platform-rbac-page .page-header-actions {
    flex-wrap: wrap;
    justify-content: flex-end;
}

.platform-rbac-page :is(input.form-input, select.form-select),
#rbac-user-modal .form-input,
#rbac-role-modal :is(.form-input, .form-select) {
    width: 100%;
    min-width: 0;
    height: 40px;
    padding: 8px 11px;
    border: 1px solid var(--border-color);
    border-radius: 8px;
    outline: none;
    background: var(--bg-primary);
    color: var(--text-primary);
    font: inherit;
    font-size: 0.8125rem;
    line-height: 1.25;
    transition: border-color 0.15s ease, box-shadow 0.15s ease, background 0.15s ease;
}

.platform-rbac-page select.form-select,
#rbac-role-modal select.form-select {
    padding-right: 32px;
}

.platform-rbac-page :is(input.form-input, select.form-select):hover,
#rbac-user-modal .form-input:hover,
#rbac-role-modal :is(.form-input, .form-select):hover {
    border-color: color-mix(in srgb, var(--accent-color) 38%, var(--border-color));
}

.platform-rbac-page :is(input.form-input, select.form-select):focus,
#rbac-user-modal .form-input:focus,
#rbac-role-modal :is(.form-input, .form-select):focus {
    border-color: var(--accent-color);
    box-shadow: 0 0 0 3px rgba(0, 102, 255, 0.12);
}

.platform-rbac-page input.form-input::placeholder,
#rbac-user-modal .form-input::placeholder,
#rbac-role-modal .form-input::placeholder {
    color: var(--text-muted);
    opacity: 1;
}

.platform-rbac-page input[type="search"]::-webkit-search-cancel-button {
    cursor: pointer;
}

.platform-rbac-page :is(.btn-primary, .btn-secondary):disabled,
#rbac-user-modal :is(.btn-primary, .btn-secondary):disabled,
#rbac-role-modal :is(.btn-primary, .btn-secondary):disabled {
    transform: none;
    box-shadow: none;
    cursor: not-allowed;
    opacity: 0.48;
}

.rbac-topbar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 14px;
    margin-bottom: 16px;
}

.rbac-overview {
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    gap: 8px;
    flex: 1 1 auto;
    margin-bottom: 0;
}

.rbac-metric {
    --rbac-metric-accent: var(--primary-color, #2563eb);
    --rbac-metric-bg: rgba(37, 99, 235, 0.09);
    --rbac-metric-border: rgba(37, 99, 235, 0.34);
    display: inline-flex;
    align-items: baseline;
    gap: 5px;
    width: fit-content;
    min-width: 0;
    padding: 7px 11px;
    border-color: var(--rbac-metric-border);
    border-radius: 999px;
    background: var(--rbac-metric-bg);
}

.rbac-metric strong {
    order: -1;
    margin-top: 0;
    color: var(--rbac-metric-accent);
    font-size: 0.9375rem;
    font-weight: 800;
    line-height: 1;
}

.rbac-metric span {
    color: var(--rbac-metric-accent);
    font-size: 0.8125rem;
    font-weight: 700;
    line-height: 1;
    white-space: nowrap;
}

.rbac-metric-users,
.rbac-metric-enabled {
    --rbac-metric-accent: #2563eb;
    --rbac-metric-bg: rgba(37, 99, 235, 0.09);
    --rbac-metric-border: rgba(37, 99, 235, 0.34);
}

.rbac-metric-roles {
    --rbac-metric-accent: #7c3aed;
    --rbac-metric-bg: rgba(124, 58, 237, 0.1);
    --rbac-metric-border: rgba(124, 58, 237, 0.34);
}

.rbac-metric-assignments {
    --rbac-metric-accent: #ea580c;
    --rbac-metric-bg: rgba(234, 88, 12, 0.1);
    --rbac-metric-border: rgba(234, 88, 12, 0.34);
}

.rbac-workspace-nav {
    flex: 0 0 auto;
    width: auto;
    margin-bottom: 0;
    align-self: center;
    border-radius: 999px;
}

.rbac-workspace-tab {
    flex: 0 0 auto;
    min-width: 0;
    padding: 7px 12px;
    border-radius: 999px;
    text-align: center;
    white-space: nowrap;
}

.rbac-workspace-tab span {
    font-size: 0.8125rem;
}

.rbac-workspace-tab small {
    display: none;
}

.rbac-layout {
    grid-template-columns: minmax(280px, 328px) minmax(0, 1fr);
    align-items: stretch;
    height: 100%;
    min-height: 0;
    overflow: hidden;
}

.rbac-panel {
    display: flex;
    flex-direction: column;
    min-height: 0;
    overflow: hidden;
    border-radius: 10px;
}

.rbac-panel-users {
    position: static;
    height: auto;
    max-height: none;
}

.rbac-panel-users .rbac-list {
    flex: 1 1 auto;
    min-height: 0;
    overflow-y: auto;
    overscroll-behavior: contain;
    padding: 4px 8px 12px;
}

.rbac-panel-detail {
    display: flex;
    flex-direction: column;
    min-width: 0;
    min-height: 0;
}

.rbac-panel-detail .rbac-detail-head,
.rbac-panel-detail .rbac-selected-summary,
.rbac-panel-detail .rbac-tabs {
    flex: 0 0 auto;
}

.rbac-panel-detail .rbac-tab-panel {
    flex: 1 1 auto;
    min-height: 0;
    overflow: hidden;
    padding: 14px;
}

.rbac-panel-detail #rbac-tab-roles.rbac-tab-panel:not([hidden]) {
    overflow-y: auto;
    overscroll-behavior: contain;
}

.rbac-panel-detail #rbac-tab-assignments.rbac-tab-panel:not([hidden]) {
    display: flex;
    flex-direction: column;
    gap: 8px;
    overflow-y: auto;
    overscroll-behavior: contain;
}

.rbac-panel-detail .rbac-selected-summary {
    padding: 0;
}

.rbac-panel-detail .rbac-selected-summary > div {
    padding: 9px 12px;
}

.rbac-panel-detail .rbac-selected-summary span {
    font-size: 0.6875rem;
}

.rbac-panel-detail .rbac-selected-summary strong {
    margin-top: 2px;
    font-size: 0.875rem;
}

.rbac-panel-detail .rbac-selected-summary .rbac-summary-count--interactive {
    margin-top: 2px;
    font-size: 0.875rem;
}

.rbac-panel-detail .rbac-detail-head {
    min-height: 0;
    padding: 8px 14px;
}

.rbac-panel-detail .rbac-detail-head h3 {
    display: flex;
    min-width: 0;
    align-items: baseline;
    flex-wrap: nowrap;
    gap: 8px;
    margin: 0;
    overflow: hidden;
    font-size: 0.9375rem;
    line-height: 1.3;
}

.rbac-detail-name {
    flex: 0 1 auto;
    min-width: 0;
    overflow: hidden;
    font-weight: 650;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.rbac-detail-meta {
    flex: 1 1 auto;
    min-width: 0;
    overflow: hidden;
    color: var(--text-secondary);
    font-size: 0.8125rem;
    font-weight: 500;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.rbac-panel-detail .rbac-detail-head .rbac-muted[hidden] {
    display: none !important;
}

.rbac-panel-detail .rbac-tabs {
    gap: 12px;
    padding: 0 12px;
}

.rbac-panel-head,
.rbac-detail-head {
    min-height: 0;
    padding: 8px 14px;
}

.rbac-detail-head > div:first-child,
.rbac-panel-head > div:first-child {
    flex: 1 1 auto;
    min-width: 0;
    overflow: hidden;
}

.rbac-detail-actions {
    flex: 0 0 auto;
    flex-wrap: nowrap;
}

.rbac-search {
    padding: 12px;
}

.rbac-search .form-input {
    min-height: 40px;
    border-radius: 8px;
}

.rbac-user-row {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    grid-template-rows: auto auto auto;
    align-items: start;
    gap: 3px 10px;
    min-height: 0;
    margin-bottom: 4px;
    padding: 9px 11px;
}

.rbac-user-meta {
    width: 100%;
    max-width: none;
}

.rbac-selected-summary {
    gap: 0;
    padding: 0;
}

.rbac-selected-summary > div {
    padding: 12px 15px;
    border-right: 1px solid var(--border-color);
}

.rbac-selected-summary > div:last-child {
    border-right: 0;
}

.rbac-tabs {
    gap: 18px;
    padding: 0 15px;
    border-bottom: 1px solid var(--border-color);
}

.rbac-tab {
    margin-bottom: -1px;
    padding: 11px 1px 10px;
    border: 0;
    border-bottom: 2px solid transparent;
    border-radius: 0;
    background: transparent;
    font-size: 0.8125rem;
}

.rbac-tab.is-active {
    border-bottom-color: var(--accent-color);
    background: transparent;
    color: var(--accent-color);
    font-weight: 600;
}

.rbac-section-toolbar {
    align-items: center;
    flex-wrap: wrap;
    row-gap: 10px;
    padding-bottom: 2px;
}

.rbac-section-toolbar > div:first-child {
    flex: 1 1 280px;
    min-width: 0;
}

.rbac-role-save-actions {
    flex: 0 0 auto;
    flex-wrap: wrap;
    justify-content: flex-end;
}

.rbac-role-grid {
    grid-template-columns: repeat(auto-fit, minmax(min(100%, 280px), 1fr));
    align-items: stretch;
    gap: 10px;
}

.rbac-role-card {
    display: grid;
    grid-template-rows: auto minmax(38px, auto) auto;
    min-width: 0;
    min-height: 158px;
    padding: 13px;
}

.rbac-role-card-head {
    align-items: flex-start;
}

.rbac-role-card-head .checkbox-label {
    min-width: 0;
}

.rbac-role-card p {
    min-height: 0;
    margin: 11px 0;
}

.rbac-role-card-foot {
    align-content: flex-start;
    justify-content: flex-start;
    gap: 6px 12px;
    padding-top: 10px;
    border-top: 1px solid var(--border-color);
    font-size: 0.75rem;
}

/* Assignment and permission choices are selections, not on/off switches. */
:is(.rbac-role-card, .rbac-resource-option, .rbac-checkbox-item) .checkbox-custom {
    width: 18px;
    height: 18px;
    border-width: 1px;
    border-radius: 5px;
    box-shadow: none;
}

:is(.rbac-role-card, .rbac-resource-option, .rbac-checkbox-item) .checkbox-custom::before {
    top: 2px;
    left: 5px;
    width: 5px;
    height: 9px;
    border: solid #fff;
    border-width: 0 2px 2px 0;
    border-radius: 0;
    background: transparent;
    box-shadow: none;
    opacity: 0;
    transform: rotate(45deg);
}

:is(.rbac-role-card, .rbac-resource-option, .rbac-checkbox-item) .modern-checkbox:checked + .checkbox-custom {
    box-shadow: 0 0 0 3px rgba(0, 102, 255, 0.10);
}

:is(.rbac-role-card, .rbac-resource-option, .rbac-checkbox-item) .modern-checkbox:checked + .checkbox-custom::before {
    opacity: 1;
    transform: rotate(45deg);
}

.rbac-assignment-toolbar {
    display: flex;
    flex-direction: column;
    align-items: stretch;
    flex-wrap: nowrap;
    gap: 8px;
    margin-bottom: 0;
}

.rbac-assignment-toolbar-main {
    display: grid;
    grid-template-columns: minmax(140px, 180px) minmax(280px, 1fr);
    align-items: end;
    gap: 10px;
}

.rbac-assignment-field--search,
.rbac-assignment-field--id {
    min-width: 0;
}

.rbac-assignment-toolbar .btn-primary {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 4px;
    min-width: 142px;
}

.platform-rbac-page :is(.rbac-detail-actions, .rbac-role-save-actions, .rbac-assignment-toolbar, .rbac-role-management-actions) .btn-primary {
    border-color: var(--accent-color);
    background: var(--accent-color);
    color: #fff;
}

.platform-rbac-page :is(.rbac-detail-actions, .rbac-role-save-actions, .rbac-assignment-toolbar, .rbac-role-management-actions) .btn-primary:hover:not(:disabled) {
    border-color: var(--accent-hover);
    background: var(--accent-hover);
}

.rbac-assignment-field .settings-custom-select-trigger,
#rbac-role-modal .settings-custom-select-trigger {
    min-height: 40px;
    height: 40px;
}

.rbac-assignment-help {
    padding: 0 2px;
}

.rbac-resource-picker {
    display: flex;
    flex: 1 1 auto;
    flex-direction: column;
    gap: 0;
    min-height: 0;
    max-height: none;
    margin: 0;
    padding: 0 12px;
    overflow-y: auto;
    overscroll-behavior: contain;
}

.rbac-resource-picker .rbac-resource-option {
    display: grid;
    grid-template-columns: auto minmax(120px, 1fr) minmax(90px, 0.75fr) minmax(60px, 0.55fr) max-content;
    gap: 10px;
    height: 58px;
    min-height: 58px;
    padding: 8px 2px;
    box-sizing: border-box;
    border: 0;
    border-bottom: 1px solid color-mix(in srgb, var(--border-color) 78%, transparent);
    border-radius: 0;
    background: transparent;
}

.rbac-resource-picker .rbac-resource-option:last-child {
    border-bottom: 0;
}

.rbac-resource-picker .rbac-resource-option:hover:not(.is-assigned) {
    background: color-mix(in srgb, var(--accent-color) 3%, var(--bg-primary));
}

.rbac-resource-picker .rbac-resource-option:has(input:checked) {
    background: color-mix(in srgb, var(--accent-color) 6%, var(--bg-primary));
}

.rbac-resource-picker .rbac-resource-option.is-assigned {
    opacity: 1;
}

.rbac-resource-picker .rbac-resource-option.is-assigned .rbac-resource-option-main {
    opacity: 0.72;
}

.rbac-resource-option-id {
    min-width: 0;
    overflow: hidden;
    color: var(--text-secondary);
    font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
    font-size: 0.75rem;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.rbac-resource-copy {
    min-height: 28px;
    padding: 3px 6px;
    font-size: 0.75rem;
}

.rbac-assignments-list {
    flex: 1 1 auto;
    gap: 0;
    min-height: 0;
    max-height: none;
    padding: 0 12px;
}

.rbac-assignments-list .rbac-assignment-row {
    display: grid;
    grid-template-columns: minmax(150px, 1.25fr) minmax(100px, 0.8fr) minmax(80px, 0.7fr) max-content;
    align-items: center;
    gap: 12px;
    height: 58px;
    min-height: 58px;
    padding: 8px 10px;
    box-sizing: border-box;
    border: 0;
    border-bottom: 1px solid color-mix(in srgb, var(--border-color) 78%, transparent);
    border-radius: 0;
    background: transparent;
}

.rbac-assignments-list .rbac-assignment-row:last-child {
    border-bottom: 0;
}

.rbac-assignments-list .rbac-assignment-row:hover {
    background: color-mix(in srgb, var(--accent-color) 3%, var(--bg-primary));
}

.rbac-assignment-identity {
    display: flex;
    align-items: center;
    gap: 8px;
    min-width: 0;
}

.rbac-assignment-identity strong {
    overflow: hidden;
    font-size: 0.8125rem;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.rbac-assignments-list .rbac-assignment-id {
    min-width: 0;
    overflow: hidden;
    color: var(--text-secondary);
    font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
    font-size: 0.75rem;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.rbac-assignment-detail {
    overflow: hidden;
    color: var(--text-secondary);
    font-size: 0.75rem;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.rbac-assignment-actions {
    display: flex;
    align-items: center;
    gap: 4px;
}

.rbac-assignment-actions .btn-link {
    min-height: 28px;
    padding: 3px 6px;
    font-size: 0.75rem;
}

.rbac-assignment-actions .btn-link.is-danger {
    color: var(--danger-color, #dc2626);
}

@container rbac-page (max-width: 720px) {
    .rbac-resource-picker .rbac-resource-option {
        grid-template-columns: auto minmax(0, 1fr) max-content;
        height: auto;
        min-height: 72px;
    }

    .rbac-resource-option-id,
    .rbac-resource-option-detail {
        grid-column: 2;
    }

    .rbac-resource-copy {
        grid-column: 3;
        grid-row: 1 / span 3;
    }

    .rbac-assignments-list .rbac-assignment-row {
        grid-template-columns: minmax(0, 1fr) max-content;
        height: auto;
        min-height: 72px;
    }

    .rbac-assignment-id,
    .rbac-assignment-detail {
        grid-column: 1;
    }

    .rbac-assignment-actions {
        grid-column: 2;
        grid-row: 1 / span 3;
    }
}

.rbac-picker-status {
    min-height: 100px;
    display: flex;
    align-items: center;
    justify-content: center;
}

.rbac-assignment-list-head {
    padding-top: 3px;
}

.rbac-role-management {
    min-height: 0;
    padding: 18px;
    border-radius: 10px;
}

.rbac-role-management-head {
    align-items: flex-end;
    flex-wrap: wrap;
    row-gap: 12px;
}

.rbac-role-management-head > div:first-child {
    flex: 1 1 320px;
    min-width: 0;
}

.rbac-role-management-actions {
    display: grid;
    grid-template-columns: minmax(240px, 340px) max-content;
    align-items: end;
    flex: 0 1 auto;
    gap: 10px;
    min-width: 0;
}

.rbac-toolbar-search {
    min-width: 0;
}

.rbac-toolbar-search label {
    display: block;
    margin-bottom: 5px;
    color: var(--text-secondary);
    font-size: 0.75rem;
    font-weight: 600;
}

.rbac-role-management-actions .form-input {
    width: 100%;
    min-height: 40px;
}

.rbac-role-management-actions .btn-primary {
    min-height: 40px;
}

.rbac-role-catalog {
    grid-template-columns: repeat(auto-fit, minmax(min(100%, 360px), 1fr));
    align-items: stretch;
}

.rbac-catalog-card {
    display: flex;
    flex-direction: column;
}

.rbac-module-tags {
    align-content: flex-start;
}

.rbac-catalog-card-foot {
    margin-top: auto;
}

#rbac-user-modal .modal-content,
#rbac-role-modal .modal-content {
    width: calc(100% - 32px);
    max-height: calc(100vh - 40px);
}

#rbac-user-modal .modal-body,
#rbac-role-modal .modal-body {
    min-height: 0;
    overflow-y: auto;
}

#rbac-user-modal .rbac-checkbox-grid {
    grid-template-columns: repeat(auto-fit, minmax(min(100%, 220px), 1fr));
}

#rbac-role-modal .rbac-permission-tools {
    grid-template-columns: minmax(220px, 1fr) max-content max-content;
    align-items: center;
}

#rbac-role-modal .rbac-permission-groups {
    max-height: min(48vh, 520px);
}

@container rbac-page (max-width: 1050px) {
    .rbac-layout {
        grid-template-columns: minmax(250px, 300px) minmax(0, 1fr);
        gap: 12px;
    }

    .rbac-role-grid {
        grid-template-columns: minmax(0, 1fr);
    }

    .rbac-assignment-toolbar-main {
        grid-template-columns: minmax(120px, 155px) minmax(220px, 1fr);
    }

    .rbac-assignment-toolbar-main .btn-primary {
        grid-column: 1 / -1;
        width: 100%;
    }
}

@container rbac-page (max-width: 760px) {
    .rbac-topbar {
        flex-direction: column;
    }

    .rbac-workspace-nav {
        flex-basis: auto;
        width: min(100%, 540px);
    }

    .rbac-resource-filterbar {
        grid-template-columns: minmax(0, 1fr);
    }

    .rbac-overview {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .rbac-layout {
        grid-template-columns: minmax(0, 1fr);
    }

    .rbac-panel-users {
        position: static;
        height: min(420px, 60vh);
        max-height: min(420px, 60vh);
    }

    .rbac-selected-summary {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .rbac-selected-summary > div:nth-child(2) {
        border-right: 0;
    }

    .rbac-selected-summary > div:nth-child(-n+2) {
        border-bottom: 1px solid var(--border-color);
    }

    .rbac-role-management-actions {
        width: 100%;
        grid-template-columns: minmax(0, 1fr) max-content;
    }

    .rbac-assignment-toolbar-main {
        grid-template-columns: minmax(120px, 160px) minmax(0, 1fr);
    }

}

@container rbac-page (max-width: 560px) {
    .rbac-workspace-nav {
        flex-direction: column;
        width: 100%;
    }

    .rbac-detail-head {
        align-items: flex-start;
        flex-direction: column;
    }

    .rbac-detail-actions,
    .rbac-detail-actions > button {
        width: 100%;
    }

    .rbac-assignment-toolbar-main,
    .rbac-role-management-actions {
        grid-template-columns: minmax(0, 1fr);
    }

    .rbac-assignment-toolbar-main .btn-primary,
    .rbac-role-management-actions .btn-primary {
        grid-column: auto;
        width: 100%;
    }

    #rbac-role-modal .rbac-permission-tools {
        grid-template-columns: minmax(0, 1fr);
    }
}

@media (max-width: 720px) {
    #rbac-user-modal .modal-content,
    #rbac-role-modal .modal-content {
        width: calc(100% - 20px);
        max-height: calc(100vh - 20px);
    }

    #rbac-role-modal .rbac-permission-tools {
        grid-template-columns: minmax(0, 1fr);
    }
}
/* Asset management */
.asset-page-subtitle { margin: 5px 0 0; color: var(--text-secondary, #6b7280); font-size: 13px; font-weight: 400; }
.asset-content { display: flex; flex-direction: column; gap: 20px; }
#page-asset-library .asset-content { overflow: visible; }
#page-asset-library .asset-toolbar { flex: 0 0 auto; }
.asset-overview-summary { display: grid; grid-template-columns: minmax(0, 1.65fr) minmax(270px, .75fr); gap: 16px; }
.asset-total-card,.asset-recent-card,.asset-panel { border: 1px solid var(--border-color, #e5e7eb); border-radius: 16px; background: var(--card-bg, #fff); box-shadow: 0 8px 24px rgba(15,23,42,.035); }
.asset-total-card { min-width: 0; padding: 22px 24px 20px; }
.asset-total-card__layout { display: grid; grid-template-columns: minmax(300px,.92fr) minmax(360px,1.08fr); align-items: stretch; gap: 24px; }
.asset-inventory-summary { display: flex; min-width: 0; flex-direction: column; }
.asset-total-card__heading { display: flex; align-items: center; gap: 12px; }
.asset-total-card__heading p { margin: 4px 0 0; color: var(--text-secondary, #6b7280); font-size: 12px; }
.asset-overview-icon { display: grid; width: 40px; height: 40px; flex: 0 0 40px; place-items: center; border-radius: 11px; }
.asset-overview-icon svg { width: 21px; height: 21px; }
.asset-overview-icon--blue { background: rgba(37,99,235,.11); color: #3b82f6; }
.asset-overview-icon--violet { background: rgba(99,102,241,.11); color: #6366f1; }
.asset-eyebrow { color: var(--text-primary, #111827); font-size: 14px; font-weight: 650; }
.asset-total-value { display: block; margin: 24px 0 22px; color: var(--text-primary, #111827); font-size: clamp(42px, 4vw, 58px); font-weight: 720; letter-spacing: -.045em; line-height: .9; }
.asset-type-grid { display: grid; grid-template-columns: repeat(3,minmax(0,1fr)); overflow: hidden; border: 1px solid var(--border-color, #e5e7eb); border-radius: 11px; background: var(--bg-secondary, #f8fafc); }
.asset-type-item { display: grid; grid-template-columns: auto minmax(0,1fr); grid-template-areas: "dot label" "value value"; align-items: center; gap: 8px; min-width: 0; padding: 11px 14px; }
.asset-type-item + .asset-type-item { border-left: 1px solid var(--border-color, #e5e7eb); }
.asset-type-item > span:not(.asset-type-dot) { grid-area: label; overflow: hidden; color: var(--text-secondary, #64748b); font-size: 11px; text-overflow: ellipsis; white-space: nowrap; }
.asset-type-item strong { grid-area: value; color: var(--text-primary, #111827); font-size: 18px; }
.asset-type-dot { grid-area: dot; width: 7px; height: 7px; border-radius: 50%; background: #3b82f6; box-shadow: 0 0 0 4px rgba(59,130,246,.10); }
.asset-type-item--domain .asset-type-dot { background: #8b5cf6; box-shadow: 0 0 0 4px rgba(139,92,246,.10); }
.asset-type-item--port .asset-type-dot { background: #14b8a6; box-shadow: 0 0 0 4px rgba(20,184,166,.10); }
.asset-protocol-compact { min-width: 0; padding-left: 24px; border-left: 1px solid var(--border-color,#e5e7eb); }
.asset-protocol-compact__header { display: flex; min-height: 40px; align-items: flex-start; justify-content: space-between; gap: 12px; margin-bottom: 14px; }
.asset-protocol-compact__header h3 { margin: 0; color: var(--text-primary,#111827); font-size: 14px; }
.asset-protocol-compact__header p { margin: 4px 0 0; color: var(--text-secondary,#64748b); font-size: 11px; }
.asset-protocol-compact .asset-protocol-columns { grid-template-columns: 94px minmax(90px,1fr) 46px 42px; padding-right: 6px; padding-left: 6px; }
.asset-protocol-compact .asset-bar-row { grid-template-columns: 94px minmax(90px,1fr) 46px 42px; min-height: 28px; padding: 2px 6px; }
.asset-protocol-compact .asset-bar-chart { min-height: 142px; }
.asset-protocol-empty { display: grid; min-height: 142px; place-content: center; text-align: center; }
.asset-protocol-empty span { color: var(--text-muted,#94a3b8); font-size: 24px; line-height: 1; }
.asset-protocol-empty p { margin: 7px 0 0; color: var(--text-secondary,#64748b); font-size: 11px; }
.asset-recent-card { display: flex; min-width: 0; flex-direction: column; overflow: hidden; padding: 22px; color: var(--text-primary,#111827); }
.asset-recent-card__top { display: flex; align-items: center; justify-content: space-between; }
.asset-recent-badge { padding: 5px 8px; border: 1px solid var(--border-color,#e5e7eb); border-radius: 999px; background: var(--bg-secondary,#f8fafc); color: var(--text-secondary,#64748b); font-size: 10px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; }
.asset-recent-card__body { display: flex; margin-top: 28px; flex-direction: column; gap: 7px; padding: 0; }
.asset-recent-card__body span { color: var(--text-secondary,#64748b); font-size: 13px; }
.asset-recent-card__body strong { font-size: clamp(38px,3.5vw,52px); font-weight: 720; letter-spacing: -.04em; line-height: 1; }
.asset-recent-progress { height: 5px; margin-top: auto; overflow: hidden; border-radius: 999px; background: var(--bg-secondary,#eef2f7); }
.asset-recent-progress i { display: block; width: 0; height: 100%; border-radius: inherit; background: linear-gradient(90deg,#3b82f6,#8b5cf6); transition: width .35s ease; }
.asset-recent-caption { margin: 9px 0 0; color: var(--text-secondary,#64748b); font-size: 11px; }
.asset-insight-heading { display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 4px 2px 0; }
.asset-insight-heading h3 { margin: 0; color: var(--text-primary,#111827); font-size: 17px; }
.asset-insight-heading p { margin: 5px 0 0; color: var(--text-secondary,#64748b); font-size: 12px; }
.asset-period-switch { display: inline-flex; padding: 3px; border: 1px solid var(--border-color,#e5e7eb); border-radius: 9px; background: var(--card-bg,#fff); }
.asset-period-switch button { min-width: 54px; height: 29px; padding: 0 10px; border: 0; border-radius: 6px; background: transparent; color: var(--text-secondary,#64748b); cursor: pointer; font: inherit; font-size: 11px; }
.asset-period-switch button:hover { color: var(--text-primary,#111827); }
.asset-period-switch button.active { background: rgba(59,130,246,.12); color: #2563eb; font-weight: 650; }
.asset-trend-grid { display: grid; grid-template-columns: repeat(2,minmax(0,1fr)); gap: 16px; }
.asset-trend-panel { min-width: 0; }
.asset-trend-panel .asset-panel-header { min-height: 42px; margin-bottom: 14px; }
.asset-trend-header { display: grid; grid-template-columns: minmax(190px,1fr) auto; grid-template-areas: "heading legend" "heading summary"; align-items: center; column-gap: 24px; row-gap: 8px; }
.asset-trend-heading { grid-area: heading; min-width: 0; }
.asset-trend-header .asset-chart-legend { grid-area: legend; }
.asset-trend-header .asset-chart-summary { grid-area: summary; justify-content: flex-end; }
.asset-chart-legend { display: flex; align-items: center; flex-wrap: wrap; justify-content: flex-end; gap: 12px; }
.asset-chart-legend span { display: inline-flex; align-items: center; gap: 5px; color: var(--text-secondary,#64748b); font-size: 10px; white-space: nowrap; }
.asset-chart-legend span::before { width: 7px; height: 7px; border-radius: 50%; background: #3b82f6; content: ''; }
.asset-chart-legend .asset-legend-inactive::before { background: #8b5cf6; }
.asset-chart-legend .asset-legend-risk::before { background: #f59e0b; }
.asset-chart-legend .asset-legend-high::before { background: #ef4444; }
.asset-line-chart { min-height: 220px; }
.asset-line-chart svg { display: block; width: 100%; height: 220px; overflow: visible; color: var(--text-muted,#94a3b8); }
.asset-chart-grid line { stroke: var(--border-color,#e5e7eb); stroke-width: 1; stroke-dasharray: 3 4; }
.asset-chart-grid text { fill: currentColor; font-size: 9px; }
.asset-chart-summary { display: flex; align-items: center; gap: 18px; padding: 0; }
.asset-chart-summary div { display: flex; align-items: baseline; gap: 6px; white-space: nowrap; }
.asset-chart-summary span { color: var(--text-secondary,#64748b); font-size: 10px; }
.asset-chart-summary strong { font-size: 17px; line-height: 1; }
.asset-coverage-layout { display: grid; grid-template-columns: 230px minmax(0,1fr); align-items: center; gap: 24px; }
.asset-coverage-overview { min-width: 0; padding: 6px 24px 6px 4px; border-right: 1px solid var(--border-color,#e5e7eb); }
.asset-coverage-gauge { --asset-coverage-value: 0%; --asset-coverage-color: #3b82f6; width: 100%; }
.asset-coverage-gauge.is-critical { --asset-coverage-color: #ef4444; }
.asset-coverage-gauge.is-warning { --asset-coverage-color: #f59e0b; }
.asset-coverage-gauge.is-healthy { --asset-coverage-color: #10b981; }
.asset-coverage-gauge::after { display: block; width: 100%; height: 5px; margin-top: 16px; border-radius: 999px; background: linear-gradient(90deg,var(--asset-coverage-color) 0 var(--asset-coverage-value),var(--bg-secondary,#eef2f7) var(--asset-coverage-value) 100%); content: ''; transition: background .3s ease; }
.asset-coverage-gauge strong,.asset-coverage-gauge span { display: block; }
.asset-coverage-gauge strong { color: var(--text-primary,#111827); font-size: 32px; letter-spacing: -.04em; line-height: 1; }
.asset-coverage-gauge span { margin-top: 7px; color: var(--text-secondary,#64748b); font-size: 11px; }
.asset-coverage-metrics { display: grid; grid-template-columns: repeat(4,minmax(0,1fr)); overflow: hidden; border: 1px solid var(--border-color,#e5e7eb); border-radius: 12px; }
.asset-coverage-metrics > div { box-sizing: border-box; min-width: 0; min-height: 104px; padding: 14px 16px; }
.asset-coverage-metrics > div + div { border-left: 1px solid var(--border-color,#e5e7eb); }
.asset-coverage-metrics span,.asset-coverage-metrics strong,.asset-coverage-metrics small { display: block; }
.asset-coverage-metrics span { color: var(--text-secondary,#64748b); font-size: 11px; }
.asset-coverage-metrics strong { margin-top: 11px; color: var(--text-primary,#111827); font-size: 24px; letter-spacing: -.025em; line-height: 1; }
.asset-coverage-metrics small { margin-top: 8px; color: var(--text-muted,#94a3b8); font-size: 9px; line-height: 1.4; }
.asset-coverage-metric--never.has-gap strong { color: #f59e0b; }
.asset-coverage-metric--stale.has-gap strong { color: #ef4444; }
.asset-panel { padding: 22px 24px 24px; }
.asset-panel-header { display: flex; align-items: flex-start; justify-content: space-between; gap: 16px; margin-bottom: 22px; }
.asset-panel-header h3 { margin: 0; font-size: 16px; }
.asset-panel-header p { margin: 6px 0 0; color: var(--text-secondary, #64748b); font-size: 12px; }
.asset-panel-meta { flex: 0 0 auto; padding: 5px 9px; border-radius: 999px; background: var(--bg-secondary, #f1f5f9); color: var(--text-secondary, #64748b); font-size: 11px; }
.asset-panel-meta.is-critical { background: rgba(239,68,68,.10); color: #dc2626; }
.asset-panel-meta.is-warning { background: rgba(245,158,11,.12); color: #d97706; }
.asset-panel-meta.is-healthy { background: rgba(16,185,129,.11); color: #059669; }
.asset-protocol-columns { display: grid; grid-template-columns: 26px 94px minmax(140px,1fr) 46px 42px; align-items: center; gap: 12px; margin-bottom: 7px; padding: 0 12px 9px; border-bottom: 1px solid var(--border-color,#e5e7eb); color: var(--text-muted,#94a3b8); font-size: 9px; }
.asset-protocol-columns span:nth-last-child(-n+2) { text-align: right; }
.asset-bar-chart { display: flex; min-width: 0; flex-direction: column; gap: 2px; }
.asset-bar-row { display: grid; grid-template-columns: 26px 94px minmax(140px,1fr) 46px 42px; min-height: 35px; align-items: center; gap: 12px; padding: 3px 12px; border-radius: 7px; transition: background .15s; }
.asset-bar-row:hover { background: var(--bg-secondary,#f8fafc); }
.asset-bar-rank { color: var(--text-muted, #94a3b8); font: 10px ui-monospace,SFMono-Regular,Menlo,monospace; }
.asset-bar-label { display: flex; align-items: center; gap: 7px; color: var(--text-primary,#111827); font-size: 11px; font-weight: 600; overflow: hidden; text-overflow: ellipsis; }
.asset-bar-label::before { width: 6px; height: 6px; flex: 0 0 6px; border-radius: 2px; background: var(--protocol-color,#3b82f6); content: ''; }
.asset-bar-track { height: 6px; overflow: hidden; border-radius: 999px; background: var(--bg-secondary, #eef2f7); }
.asset-bar-track i { display: block; height: 100%; border-radius: inherit; background: var(--protocol-color,#3b82f6); }
.asset-bar-row strong,.asset-bar-row small { text-align: right; }
.asset-bar-row strong { font-size: 11px; }
.asset-bar-row small { color: var(--text-secondary, #6b7280); font-size: 11px; }
.asset-toolbar { display: flex; align-items: stretch; gap: 12px; flex-direction: column; padding: 14px; border: 1px solid var(--border-color, #e5e7eb); border-radius: 12px; background: var(--card-bg, #fff); }
.asset-toolbar-main { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
.asset-toolbar-main > input { min-width: 300px; flex: 1; }
.asset-toolbar select { min-width: 130px; }
.asset-toolbar input,.asset-toolbar select { height: 38px; padding: 0 12px; border: 1px solid var(--border-color, #d8dee8); border-radius: 8px; background: var(--input-bg, #fff); color: var(--text-primary, #111827); }
.asset-advanced-filters { display: grid; grid-template-columns: repeat(5,minmax(140px,1fr)); gap: 12px; padding-top: 14px; border-top: 1px solid var(--border-color,#e5e7eb); }
.asset-advanced-filters[hidden] { display: none; }
.asset-advanced-filters label { display: flex; min-width: 0; flex-direction: column; gap: 6px; color: var(--text-secondary,#64748b); font-size: 11px; font-weight: 600; }
.asset-advanced-filters input,.asset-advanced-filters select { box-sizing: border-box; width: 100%; min-width: 0; font-size: 12px; font-weight: 400; }
.asset-saved-views { display: flex; align-items: center; gap: 9px; padding-top: 12px; border-top: 1px dashed var(--border-color,#e5e7eb); }
.asset-saved-views select { min-width: 220px; }
.asset-custom-select { width: 100%; min-width: 0; font-weight: 400; }
.asset-custom-select--filter { width: auto; min-width: 150px; flex: 0 0 auto; }
.asset-advanced-filters .asset-custom-select--filter { width: 100%; min-width: 0; }
.asset-custom-select--saved-view { width: 220px; min-width: 220px; flex: 0 0 220px; }
.asset-custom-select .settings-custom-select-trigger { height: 42px; min-height: 42px; border-color: var(--border-color, #d8dee8); border-radius: 8px; background: var(--input-bg, #fff); color: var(--text-primary, #111827); font-size: 13px; font-weight: 400; }
.asset-custom-select .settings-custom-select-caret { width: 16px; height: 16px; color: var(--text-secondary, #64748b); font-size: 0; }
