html[data-theme="dark"] .project-folder-preview-title {
    color: #f8fafc;
}

html[data-theme="dark"] .project-folder-preview-stats,
html[data-theme="dark"] .project-folder-preview-detail,
html[data-theme="dark"] .project-folder-preview-edit {
    color: #cbd5e1;
}

html[data-theme="dark"] .project-folder-preview-details {
    border-color: rgba(148, 163, 184, 0.2);
}

html[data-theme="dark"] .project-folder-preview-edit:hover,
html[data-theme="dark"] .project-folder-preview-edit:focus-visible {
    background: rgba(148, 163, 184, 0.13);
    color: #ffffff;
