.project-task-status-group {
    min-width: 0;
    display: inline-flex;
    align-items: center;
    gap: 6px;
    flex: 0 0 auto;
}

.project-task-status {
    display: inline-block;
    flex: 0 0 auto;
    border-radius: 50%;
}

.project-task-status--running {
    width: 11px;
    height: 11px;
    border: 1.5px solid #2563eb;
    border-top-color: rgba(37, 99, 235, 0.18);
    animation: project-task-status-spin 0.9s linear infinite;
}

.project-task-status--unread {
    width: 6px;
    height: 6px;
    background: #2563eb;
}

.project-task-status--approval {
    position: relative;
    display: inline-flex;
    align-items: center;
    gap: 5px;
    width: auto;
    min-height: 22px;
    padding: 2px 8px 4px;
    overflow: hidden;
    border-radius: 999px;
    background: #dcfce7;
    color: #16804a;
    font-size: 0.72rem;
    font-weight: 650;
    line-height: 18px;
    white-space: nowrap;
}

