    font-size: 0.66rem;
    font-variant-numeric: tabular-nums;
    opacity: 0.78;
}

.project-approval-progress {
    position: absolute;
    right: 0;
    bottom: 0;
    left: 0;
    height: 2px;
    background: color-mix(in srgb, currentColor 16%, transparent);
}

.project-approval-progress-value {
    display: block;
    width: 100%;
    height: 100%;
    background: currentColor;
    transition: width 0.25s linear;
}

.project-task-status--approval.is-expired {
    background: #fee2e2;
    color: #b42318;
}

.project-task-status--approval-summary {
    padding-bottom: 2px;
    transition: background-color 0.25s ease, color 0.25s ease;
}

.project-task-status--approval.is-urgency-normal {
    background: #dcfce7;
    color: #16804a;
}

.project-task-status--approval.is-urgency-warning {
    background: #fef9c3;
    color: #9a6700;
}

.project-task-status--approval.is-urgency-critical {
    background: #fee2e2;
    color: #b42318;
}

html[data-theme="dark"] .project-task-status--running {
    border-color: #60a5fa;
    border-top-color: rgba(96, 165, 250, 0.2);
}

html[data-theme="dark"] .project-task-status--unread {
    background: #60a5fa;
}

html[data-theme="dark"] .project-task-status--approval {
    background: rgba(52, 211, 153, 0.16);
    color: #6ee7b7;
}

html[data-theme="dark"] .project-task-status--approval.is-expired {
    background: rgba(248, 113, 113, 0.16);
    color: #fca5a5;
}

html[data-theme="dark"] .project-task-status--approval.is-urgency-normal {
    background: rgba(52, 211, 153, 0.16);
    color: #6ee7b7;
}

html[data-theme="dark"] .project-task-status--approval.is-urgency-warning {
    background: rgba(250, 204, 21, 0.17);
    color: #fde047;
}

html[data-theme="dark"] .project-task-status--approval.is-urgency-critical {
    background: rgba(248, 113, 113, 0.16);
    color: #fca5a5;
}

.project-conversation-preview-status.is-approval,
html[data-theme="dark"] .project-conversation-preview-status.is-approval {
    color: #22a06b;
}

html[data-theme="dark"] .project-folders-load-more {
    color: #94a3b8;
}

html[data-theme="dark"] .project-folders-load-more:hover,
html[data-theme="dark"] .project-folders-load-more:focus-visible {
    background: rgba(148, 163, 184, 0.1);
    color: #d7dee9;
}

html[data-theme="dark"] .project-folders-load-more-count {
    background: rgba(148, 163, 184, 0.14);
    color: #aeb9c9;
}

@keyframes project-task-status-spin {
    to { transform: rotate(360deg); }
}

.project-folders-empty {
    padding: 12px 8px;
    color: #9aa1ad;
    font-size: 0.8125rem;
    text-align: center;
}

.conversation-sidebar .recent-conversations-section {
    margin: 0;
    padding: 8px 0 13px;
}

.recent-conversations-toggle {
    width: 100%;
    min-height: 30px;
    margin: 0 !important;
    padding: 0 8px !important;
    border: 0;
    border-radius: 7px;
    background: transparent;
    color: inherit;
    font: inherit;
    cursor: pointer;
}

.recent-conversations-toggle:hover {
    background: #f3f4f6;
}

.recent-conversations-toggle-meta {
    display: inline-flex;
    align-items: center;
    gap: 12px;
    flex: 0 0 auto;
    color: #7c8592;
}

.recent-conversations-count {
    min-width: 1.5em;
    font-size: 0.75rem;
    font-variant-numeric: tabular-nums;
    text-align: right;
}

.recent-conversations-chevron {
    transition: transform 0.16s ease;
}

.recent-conversations-toggle[aria-expanded="true"] .recent-conversations-chevron {
    transform: rotate(90deg);
}

.recent-conversations-body[hidden] {
    display: none !important;
}

.conversation-sidebar-pagination[hidden] {
    display: none !important;
}

.conversation-sidebar:has(.recent-conversations-section.is-collapsed) .conversation-sidebar-pagination {
    display: none !important;
}

.recent-conversations-actions {
    justify-content: flex-end;
    min-height: 28px;
    margin: 5px 5px 3px;
}

.recent-conversations-body .conversation-group-title {
    padding-top: 7px;
}

.recent-conversations-body .conversation-item {
    padding: 8px;
}

html[data-theme="dark"] .conversation-sidebar,
html[data-theme="dark"] .conversation-sidebar-header {
    background: var(--bg-primary);
}

html[data-theme="dark"] .conversation-sidebar .conversation-search-box input {
    background: var(--bg-primary);
    border-color: var(--border-color);
}

html[data-theme="dark"] .project-folder-item,
html[data-theme="dark"] .project-conversation-item {
    color: var(--text-primary);
}

html[data-theme="dark"] .project-folder-item:hover,
html[data-theme="dark"] .project-conversation-item:hover,
html[data-theme="dark"] .project-conversation-row:hover .project-conversation-item,
html[data-theme="dark"] .recent-conversations-toggle:hover {
    background: var(--bg-tertiary);
}

html[data-theme="dark"] .project-folder-action:hover,
html[data-theme="dark"] .project-folder-action:focus-visible,
html[data-theme="dark"] .project-conversation-menu:hover,
html[data-theme="dark"] .project-conversation-menu:focus-visible {
    background: rgba(71, 85, 105, 0.28);
    color: var(--text-primary);
    box-shadow: none;
}

html[data-theme="dark"] .project-conversation-item.is-selected {
    background: rgba(148, 163, 184, 0.13);
    color: var(--text-primary);
    box-shadow: none;
}

html[data-theme="dark"] .project-conversation-row:hover .project-conversation-item.is-selected {
    background: rgba(148, 163, 184, 0.19);
}

@media (max-width: 900px) {
    .conversation-sidebar {
        width: 260px;
    }

    .conversation-sidebar.collapsed {
        width: 56px;
    }
}

/* ============================================================================
   Layered chat composer: Codex-style hierarchy with CyberStrikeAI controls
   ============================================================================ */

.chat-input-container {
    position: relative;
    isolation: isolate;
    display: flex;
    flex-direction: column;
    align-items: stretch;
    gap: 0;
    width: 100%;
    padding: 0 22px 14px;
    border-top: 0;
    background: transparent;
    box-sizing: border-box;
    container-name: chat-composer;
    container-type: inline-size;
}

/* The composer is an isolated stacking context. Lift that whole context while the
   settings popover is open so the turn rail and its preview cannot paint above it. */
.chat-input-container.is-session-settings-open {
    z-index: 121;
}

.chat-composer-context {
    position: relative;
    z-index: 1;
    display: flex;
    align-items: center;
    min-height: 52px;
    margin: 0 30px -9px;
    padding: 0 15px 9px;
    border: 1px solid rgba(15, 23, 42, 0.08);
    border-bottom: 0;
    border-radius: 22px 22px 0 0;
    background: #f5f6f7;
    box-shadow: 0 -8px 28px rgba(15, 23, 42, 0.035);
    box-sizing: border-box;
}

.chat-composer-context .chat-input-leading {
    align-items: center;
    gap: 0;
    min-width: 0;
}

.chat-composer-context .chat-input-leading > * {
    position: relative;
    min-width: 0;
}

.chat-composer-context .chat-input-leading > *:not(:last-child) {
    margin-right: 4px;
    padding-right: 5px;
}

.chat-composer-context .chat-input-leading > *:not(:last-child)::after {
    content: '';
    position: absolute;
    top: 11px;
    right: 0;
    bottom: 11px;
    width: 1px;
    background: rgba(15, 23, 42, 0.09);
}

.chat-composer-context .role-selector-btn {
    height: 40px;
    padding: 0 12px;
    gap: 8px;
    border: 0;
    border-radius: 12px;
    background: transparent;
    box-shadow: none;
    color: #20242a;
    font-size: 14px;
    font-weight: 560;
}

.chat-composer-context .role-selector-btn:hover,
.chat-composer-context .role-selector-btn.active {
    border: 0;
    background: rgba(15, 23, 42, 0.055);
    box-shadow: none;
}

.chat-composer-context .role-selector-btn:focus-visible {
    outline: 2px solid rgba(0, 102, 255, 0.38);
    outline-offset: -2px;
}

.chat-composer-context .role-selector-icon {
    width: 20px;
    min-width: 20px;
    height: 20px;
    font-size: 18px;
}

.chat-composer-context .role-selector-icon svg {
    display: block;
}

.chat-composer-context .role-selector-text {
    color: #20242a;
    font-size: 14px;
    font-weight: 560;
}

.chat-composer-context .role-selector-arrow {
    color: #737b87;
}

.chat-composer-surface.chat-input-primary-row {
    position: relative;
    z-index: 2;
    display: flex;
    flex: 0 0 auto;
    flex-direction: column;
    align-items: stretch;
    gap: 0;
    width: 100%;
    min-width: 0;
    min-height: 118px;
    padding: 0;
    border: 1px solid rgba(15, 23, 42, 0.12);
    border-radius: 22px;
    background: #fff;
    box-shadow: 0 14px 34px rgba(15, 23, 42, 0.08), 0 2px 7px rgba(15, 23, 42, 0.05);
    box-sizing: border-box;
    transition: border-color 0.18s ease, box-shadow 0.18s ease;
}

.chat-composer-surface.chat-input-primary-row:focus-within {
    border-color: rgba(0, 102, 255, 0.38);
    box-shadow: 0 16px 38px rgba(15, 23, 42, 0.09), 0 0 0 3px rgba(0, 102, 255, 0.07);
}

.chat-input-container .chat-composer-surface .chat-input-with-files {
    flex: 1;
    gap: 0;
    width: 100%;
    padding: 0;
}

.chat-composer-surface .chat-file-list:not(:empty) {
    padding: 18px 22px 0;
}

.chat-composer-surface .chat-upload-progress-row:not([hidden]) {
    margin: 12px 22px 0;
}

.chat-composer-surface .chat-input-field {
    min-height: 58px;
}

.chat-input-container .chat-composer-surface .chat-input-field > #chat-input {
    width: 100%;
    height: 58px;
    min-height: 58px;
    max-height: 180px;
    padding: 17px 22px 6px;
    border: 0;
    border-radius: 22px 22px 8px 8px;
    background: transparent;
    color: var(--text-primary);
    font-family: inherit;
    font-size: 15px;
    font-weight: 450;
    line-height: 1.55;
    box-shadow: none;
    resize: none;
    box-sizing: border-box;
}

.chat-input-container .chat-composer-surface .chat-input-field > #chat-input:focus {
    border: 0;
    background: transparent;
    box-shadow: none;
}

.chat-input-container .chat-composer-surface .chat-input-field > #chat-input::placeholder {
    color: #a0a6af;
    opacity: 1;
}

.chat-composer-footer {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 16px;
    min-height: 50px;
    padding: 2px 12px 9px 14px;
}

.chat-composer-footer-leading,
.chat-composer-footer-trailing {
    display: flex;
    align-items: center;
    min-width: 0;
}

.chat-composer-footer-leading {
    gap: 5px;
}

.chat-composer-footer-trailing {
    justify-content: flex-end;
    gap: 5px;
}

.chat-input-container .chat-upload-btn {
    width: 36px;
    height: 36px;
    border: 0;
    border-radius: 10px;
    background: transparent;
    color: #31363d;
    box-shadow: none;
}

.chat-input-container .chat-upload-btn:hover {
    border: 0;
    background: rgba(15, 23, 42, 0.055);
    color: #111827;
}

.chat-session-shortcut {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 7px;
    min-width: 0;
    height: 36px;
    padding: 0 10px;
    border: 0;
    border-radius: 10px;
    background: transparent;
    color: #767d87;
    font-family: inherit;
    font-size: 13px;
    font-weight: 520;
    line-height: 1;
    white-space: nowrap;
    cursor: pointer;
    transition: background 0.16s ease, color 0.16s ease;
}

.chat-session-shortcut:hover {
    background: rgba(15, 23, 42, 0.055);
    color: #272c33;
}

.chat-session-shortcut:focus-visible {
    outline: 2px solid rgba(0, 102, 255, 0.35);
    outline-offset: -2px;
}

.chat-hitl-shortcut {
    color: #777e88;
}

.chat-hitl-shortcut > span {
    display: block;
    min-width: 0;
    padding-block: 1px;
    overflow: hidden;
    text-overflow: ellipsis;
    line-height: 1.4;
}

.chat-session-shortcut-chevron {
    flex-shrink: 0;
    color: #8f96a0;
}

.chat-session-meta {
    padding-right: 8px;
    padding-left: 8px;
    color: #666d77;
    font-size: 13px;
}

.chat-model-shortcut-wrap {
    position: relative;
    display: inline-flex;
    align-items: center;
    min-width: 0;
}

.chat-model-shortcut-effort {
    color: #9299a3;
    font-weight: 470;
}

.chat-system-model-caret {
    flex: 0 0 auto;
    transition: transform 0.16s ease;
}

#chat-model-shortcut.active .chat-system-model-caret {
    transform: rotate(180deg);
}

.chat-system-model-menu {
    position: absolute;
    right: 0;
    bottom: calc(100% + 10px);
    z-index: 2200;
    display: flex;
    width: min(320px, calc(100vw - 32px));
    max-height: 320px;
    flex-direction: column;
    overflow: hidden;
    border: 1px solid var(--border-color, #dbe1ea);
    border-radius: 14px;
    background: var(--bg-primary, #fff);
    box-shadow: 0 18px 48px rgba(15, 23, 42, 0.18), 0 3px 10px rgba(15, 23, 42, 0.08);
    animation: chat-system-model-menu-in 0.16s ease-out;
}

.chat-system-model-menu[hidden] {
    display: none;
}

.chat-system-model-main[hidden],
.chat-system-model-subview[hidden] {
    display: none;
}

@keyframes chat-system-model-menu-in {
    from {
        opacity: 0;
        transform: translateY(5px) scale(0.98);
    }
    to {
        opacity: 1;
        transform: translateY(0) scale(1);
    }
}

.chat-system-model-menu-header {
    display: grid;
    grid-template-columns: 28px minmax(0, 1fr) auto;
    min-height: 52px;
    align-items: center;
    gap: 10px;
    padding: 8px 12px 8px 8px;
    border-bottom: 1px solid var(--border-color, #e5e7eb);
    color: var(--text-primary, #111827);
    font-size: 13px;
}

.chat-system-model-main {
    position: relative;
    padding: 10px;
}

.chat-system-model-setting-row {
    display: flex;
    width: 100%;
    min-height: 48px;
    align-items: center;
    justify-content: space-between;
    gap: 14px;
    padding: 9px 10px;
    border: 0;
    border-radius: 10px;
    background: transparent;
    color: var(--text-primary, #111827);
    font-family: inherit;
    cursor: pointer;
}

.chat-system-model-setting-row:hover {
    background: rgba(15, 23, 42, 0.055);
}

.chat-system-model-setting-label {
    font-size: 15px;
    font-weight: 650;
}

.chat-system-model-setting-value {
    display: inline-flex;
    min-width: 0;
    align-items: center;
    gap: 8px;
    color: var(--text-secondary, #727984);
    font-size: 14px;
    font-weight: 500;
}

.chat-system-model-setting-value > span {
    max-width: 170px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.chat-system-model-back {
    display: inline-flex;
    width: 28px;
    height: 28px;
    align-items: center;
    justify-content: center;
    padding: 0;
    border: 0;
    border-radius: 8px;
    background: transparent;
    color: var(--text-secondary, #727984);
    cursor: pointer;
}

.chat-system-model-back:hover {
    background: rgba(15, 23, 42, 0.065);
    color: var(--text-primary, #111827);
}

.chat-system-model-subview {
    display: flex;
    min-height: 128px;
    flex-direction: column;
}

.chat-system-model-status {
    min-width: 0;
    overflow: hidden;
    color: var(--text-muted, #8a929d);
    font-size: 11px;
    font-weight: 500;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.chat-system-model-status[data-tone="success"] {
    color: var(--success-color, #16a067);
}

.chat-system-model-status[data-tone="error"] {
    color: var(--error-color, #dc3545);
}

.chat-system-model-status-live {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border: 0;
}

.chat-system-model-list {
    min-height: 46px;
    overflow-y: auto;
    padding: 6px;
    scrollbar-width: thin;
}

.chat-system-model-option,
.chat-system-model-retry {
    display: flex;
    width: 100%;
    min-height: 40px;
    align-items: center;
    justify-content: space-between;
    gap: 10px;
    padding: 8px 10px;
    border: 0;
    border-radius: 9px;
    background: transparent;
    color: var(--text-primary, #111827);
    font-family: inherit;
    font-size: 13px;
    text-align: left;
    cursor: pointer;
}

.chat-system-model-option:hover:not(:disabled),
.chat-system-model-option.is-selected,
.chat-system-model-retry:hover {
    background: rgba(0, 102, 255, 0.08);
}

.chat-system-model-option:disabled {
    opacity: 0.55;
    cursor: wait;
}

.chat-system-model-option-label {
    min-width: 0;
    overflow: hidden;
    font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.chat-system-effort-option-label {
    font-family: inherit;
}

.chat-system-channel-option-label {
    font-family: inherit;
}

.chat-system-model-section-divider {
    height: 1px;
    margin: 5px 10px;
    background: var(--border-color, #e5e7eb);
}

.chat-system-model-current {
    flex: 0 0 auto;
    padding: 3px 7px;
    border-radius: 999px;
    background: rgba(0, 102, 255, 0.12);
    color: var(--accent-color, #0666ee);
    font-size: 10px;
    font-weight: 700;
}

.chat-system-model-retry {
    justify-content: center;
    color: var(--accent-color, #0666ee);
    font-weight: 650;
}

.chat-composer-meta-divider {
    width: 1px;
    height: 18px;
    margin: 0 1px;
    background: rgba(15, 23, 42, 0.1);
}

.chat-input-container .send-btn {
    width: 40px;
    min-width: 40px;
    height: 40px;
    padding: 0;
    border: 0;
    border-radius: 50%;
    background: linear-gradient(145deg, #1b7aff 0%, #0666ee 100%);
    box-shadow: 0 6px 15px rgba(0, 102, 255, 0.24), inset 0 1px 0 rgba(255, 255, 255, 0.18);
}

.chat-input-container .send-btn:hover {
    background: linear-gradient(145deg, #126fe8 0%, #005bd8 100%);
    box-shadow: 0 8px 18px rgba(0, 102, 255, 0.3), inset 0 1px 0 rgba(255, 255, 255, 0.2);
}

.chat-input-container .send-btn svg {
    display: block;
    position: absolute;
    top: 50%;
    left: 50%;
    width: 18px;
    height: 18px;
    transform: translate(-50%, -50%);
    transition: transform 0.18s ease;
}

.chat-input-container .send-btn:hover svg {
    transform: translate(-50%, -50%);
}

.chat-input-container .send-btn:active svg {
    transform: translate(-50%, -50%);
}

.chat-input-container .send-btn-label {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border: 0;
}

html[data-theme="dark"] .chat-input-container {
    background: transparent !important;
}

html[data-theme="dark"] .chat-composer-context {
    border-color: #263244;
    background: #172033;
    box-shadow: 0 -8px 28px rgba(0, 0, 0, 0.15);
}

html[data-theme="dark"] .chat-composer-context .role-selector-btn {
    border: 0 !important;
    background: transparent !important;
    color: var(--text-primary);
}

html[data-theme="dark"] .chat-composer-context .role-selector-btn:hover,
html[data-theme="dark"] .chat-composer-context .role-selector-btn.active {
    border: 0 !important;
    background: rgba(148, 163, 184, 0.1) !important;
}

html[data-theme="dark"] .chat-composer-context .role-selector-text {
    color: var(--text-primary);
}

html[data-theme="dark"] .chat-composer-context .chat-input-leading > *:not(:last-child)::after,
html[data-theme="dark"] .chat-composer-meta-divider {
    background: rgba(148, 163, 184, 0.18);
}

html[data-theme="dark"] .chat-composer-surface.chat-input-primary-row {
    border-color: #2b374b !important;
    background: #0f172a !important;
}

/* Keep the rounded surface as the sole dark background painter. Rectangular
   child backgrounds otherwise cover the color exposed by its top corners. */
html[data-theme="dark"] .chat-input-container .chat-composer-surface .chat-input-with-files,
html[data-theme="dark"] .chat-input-container .chat-composer-surface .chat-input-field {
    background: transparent !important;
}

html[data-theme="dark"] .chat-input-container .chat-composer-surface .chat-input-field > #chat-input {
    border: 0 !important;
    background: transparent !important;
}

html[data-theme="dark"] .chat-input-container .chat-upload-btn {
    border: 0 !important;
    background: transparent !important;
    color: var(--text-secondary);
}

html[data-theme="dark"] .chat-input-container .chat-upload-btn:hover,
html[data-theme="dark"] .chat-session-shortcut:hover {
    background: rgba(148, 163, 184, 0.11) !important;
    color: var(--text-primary);
}

html[data-theme="dark"] .chat-session-shortcut {
    color: var(--text-secondary);
}

html[data-theme="dark"] .chat-system-model-menu {
    border-color: #334155;
    background: #111a2b;
    box-shadow: 0 20px 52px rgba(0, 0, 0, 0.45), 0 3px 10px rgba(0, 0, 0, 0.25);
}

html[data-theme="dark"] .chat-system-model-menu-header {
    border-color: #263244;
}

html[data-theme="dark"] .chat-system-model-setting-row:hover,
html[data-theme="dark"] .chat-system-model-back:hover {
    background: rgba(148, 163, 184, 0.11);
}

html[data-theme="dark"] .chat-system-model-option:hover:not(:disabled),
