/* Composer-anchored session settings. The original controls are moved here at runtime
   so AI channel, reasoning and approval configuration keep one shared source of truth. */
.chat-composer-surface > .chat-session-settings-popover {
    position: absolute;
    z-index: 120;
    left: 16px;
    bottom: 60px;
    width: min(360px, calc(100% - 32px));
    max-height: min(68vh, 620px);
    padding: 14px;
    overflow: hidden;
    border: 1px solid rgba(148, 163, 184, 0.3);
    border-radius: 18px;
    background: rgba(255, 255, 255, 0.99);
    box-shadow: 0 22px 54px rgba(15, 23, 42, 0.2), 0 4px 12px rgba(15, 23, 42, 0.08);
    box-sizing: border-box;
    transform: translateY(0);
    transform-origin: left bottom;
    opacity: 1;
    visibility: visible;
    pointer-events: auto;
    transition: opacity 0.16s ease, transform 0.16s ease, visibility 0.16s ease;
}

.chat-composer-surface > .chat-session-settings-popover.conversation-reasoning-collapsed {
    display: block !important;
    width: min(360px, calc(100% - 32px));
    height: auto;
    min-height: 0;
    padding: 14px;
    border: 1px solid rgba(148, 163, 184, 0.3);
    opacity: 0;
    visibility: hidden;
    pointer-events: none;
    transform: translateY(8px) scale(0.985);
}

.chat-composer-surface > .chat-session-settings-popover .conversation-reasoning-card-header {
    min-height: 40px;
}

.chat-composer-surface > .chat-session-settings-popover .conversation-reasoning-body {
    max-height: calc(min(68vh, 620px) - 62px);
    padding: 8px 2px 2px;
    overflow-x: hidden;
    overflow-y: auto;
}

.chat-composer-surface > .chat-session-settings-popover .conversation-reasoning-chevron {
    transform: rotate(90deg);
}

.chat-input-container .send-btn .send-btn-stop-icon {
    position: absolute;
    top: 50%;
    left: 50%;
    display: none;
    width: 13px;
    height: 13px;
    border-radius: 2px;
    background: #fff;
    transform: translate(-50%, -50%);
}

.chat-input-container .send-btn.is-task-running,
.chat-input-container .send-btn.is-task-running:hover,
.chat-input-container .send-btn.is-task-running:active {
    background: #1f2227;
    box-shadow: 0 6px 16px rgba(15, 23, 42, 0.22), inset 0 1px 0 rgba(255, 255, 255, 0.08);
}

.chat-input-container .send-btn.is-task-running svg {
    display: none;
}

.chat-input-container .send-btn.is-task-running .send-btn-stop-icon {
    display: block;
}

html[data-theme="dark"] .chat-composer-surface > .chat-session-settings-popover {
    border-color: #334155;
    background: rgba(15, 23, 42, 0.99);
    box-shadow: 0 22px 54px rgba(0, 0, 0, 0.42), 0 4px 12px rgba(0, 0, 0, 0.24);
}

@media (prefers-reduced-motion: reduce) {
    .chat-composer-surface > .chat-session-settings-popover {
        transition: none;
    }
}

/* Codex-style assistant turn: execution narrative first, durable answer second. */
.message.assistant-turn-with-process,
.message.progress-message {
    margin-bottom: 32px;
}

.message.assistant-turn-with-process .message-content,
.message.progress-message .message-content {
    flex-basis: min(920px, 100%);
    max-width: min(86%, 920px);
}

.message.assistant-turn-with-process .mcp-call-section {
    order: 0;
}

.message.assistant-turn-with-process .assistant-final-result {
    order: 1;
    width: 100%;
    max-width: none;
    margin-top: 18px;
    padding: 0 0 2px;
    border: 0;
    border-radius: 0;
    background: transparent;
    box-shadow: none;
    overflow-x: visible;
    font-size: 0.975rem;
    line-height: 1.72;
}

.message.assistant-turn-with-process .message-time,
.message.assistant-turn-with-process .message-meta-footer {
    order: 2;
}

.message.assistant-turn-with-process .assistant-final-result > :first-child {
    margin-top: 0;
}

.message.assistant-turn-with-process .assistant-final-result > :last-child:not(.message-copy-btn) {
    margin-bottom: 0;
}

.message.assistant-turn-with-process .mcp-call-section {
    width: 100%;
    margin: 0;
    padding: 0;
    border: 0;
}

.turn-process-summary.mcp-call-label,
.progress-summary-toggle.turn-process-summary {
    appearance: none;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    width: 100%;
    min-height: 44px;
    margin: 0;
    padding: 8px 2px 11px;
    border: 0;
    border-bottom: 1px solid color-mix(in srgb, var(--border-color) 72%, transparent);
    border-radius: 0;
    background: transparent;
    color: var(--text-muted);
    font: inherit;
    font-size: 0.91rem;
    font-weight: 500;
    line-height: 1.35;
    text-align: left;
    cursor: pointer;
}

.turn-process-summary.mcp-call-label::before {
    display: none;
}

.turn-process-summary:hover,
.turn-process-summary:focus-visible {
    color: var(--text-secondary);
}

.turn-process-summary:focus-visible {
    outline: 2px solid color-mix(in srgb, var(--accent-color) 58%, transparent);
    outline-offset: 3px;
    border-radius: 4px;
}

.turn-process-leading {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    min-width: 0;
    flex-wrap: wrap;
}

.turn-process-status-dot {
    width: 6px;
    height: 6px;
    flex: 0 0 6px;
    border-radius: 50%;
    background: #a8adb5;
}

.turn-process-status-dot.is-running {
    background: var(--accent-color, #0b6cff);
    box-shadow: 0 0 0 4px color-mix(in srgb, var(--accent-color, #0b6cff) 10%, transparent);
    animation: codex-turn-pulse 1.55s ease-in-out infinite;
}

.turn-process-token-chip {
    display: inline;
    padding: 0;
    border: 0;
    border-radius: 0;
    background: transparent;
    color: inherit;
    font-size: inherit;
    font-weight: inherit;
    line-height: inherit;
    opacity: 0.72;
    white-space: nowrap;
}

.turn-process-token-chip::before {
    content: "· ";
    color: inherit;
    font-weight: inherit;
}

@keyframes codex-turn-pulse {
    0%, 100% { opacity: 0.55; transform: scale(0.88); }
    50% { opacity: 1; transform: scale(1); }
}

.turn-process-chevron {
    width: 18px;
    height: 18px;
    flex: 0 0 18px;
    color: #a4a8ae;
    transition: transform 0.18s ease;
}

.turn-process-summary.is-expanded .turn-process-chevron {
    transform: rotate(90deg);
}

.message.assistant-turn-with-process .mcp-call-toolbar {
    display: none;
}

.message.assistant-turn-with-process .mcp-tool-list,
.message.assistant-turn-with-process .mcp-tool-list.expanded {
    display: none;
}

.message.assistant-turn-with-process .process-details-container {
    margin: 0;
    padding: 0;
    border: 0;
}

.message.assistant-turn-with-process .process-details-content .progress-timeline.expanded {
    max-height: min(64vh, 720px);
    margin-top: 4px;
    padding-top: 8px;
}

.message.progress-message .progress-container {
    width: 100%;
    max-width: none;
    padding: 0;
    border: 0;
    border-radius: 0;
    background: transparent;
    box-shadow: none;
}

.message.progress-message .progress-header {
    margin: 0;
    padding: 0;
    border: 0;
}

.message.progress-message .progress-actions,
.message.progress-message .progress-footer {
    display: none;
}

.message.progress-message .progress-stage {
    margin: 10px 0 3px 24px;
    color: var(--text-primary);
    font-size: 0.9rem;
    font-weight: 500;
    line-height: 1.5;
}

.message.progress-message .progress-timeline.expanded {
    max-height: min(64vh, 720px);
    overflow-x: hidden;
    overflow-y: auto;
    overscroll-behavior: auto;
    scrollbar-gutter: stable;
}

/* Open-document execution timeline. */
.message.assistant-turn-with-process .progress-timeline,
.message.progress-message .progress-timeline {
    position: relative;
    padding: 5px 0 7px 22px;
}

.message.assistant-turn-with-process .progress-timeline::before,
.message.progress-message .progress-timeline::before {
    content: "";
    position: absolute;
    top: 11px;
    bottom: 12px;
    left: 7px;
    width: 1px;
    background: color-mix(in srgb, var(--border-color) 82%, transparent);
}

.message.assistant-turn-with-process .timeline-item,
.message.progress-message .timeline-item {
    position: relative;
    margin: 0;
    padding: 7px 0 7px 13px !important;
    border: 0 !important;
    border-radius: 0 !important;
    background: transparent !important;
    box-shadow: none !important;
    content-visibility: auto;
    contain-intrinsic-size: auto 38px;
}

.message.assistant-turn-with-process .timeline-item::before,
.message.progress-message .timeline-item::before {
    content: "";
    position: absolute;
    top: 16px;
    left: -18px;
    width: 7px;
    height: 7px;
    border: 2px solid var(--bg-primary);
    border-radius: 50%;
    background: #a7adb5;
    box-sizing: border-box;
    z-index: 1;
}

.message.assistant-turn-with-process .timeline-item-tool_call::before,
.message.progress-message .timeline-item-tool_call::before {
    background: var(--accent-color, #0b6cff);
}

.message.assistant-turn-with-process .timeline-item-tool_call.tool-call-completed::before,
.message.progress-message .timeline-item-tool_call.tool-call-completed::before {
    background: var(--success-color, #36a854);
}

.message.assistant-turn-with-process .timeline-item-tool_call.tool-call-failed::before,
.message.progress-message .timeline-item-tool_call.tool-call-failed::before,
.message.assistant-turn-with-process .timeline-item-error::before,
.message.progress-message .timeline-item-error::before {
    background: var(--error-color, #dc3545);
}

.message.assistant-turn-with-process .timeline-item-header,
.message.progress-message .timeline-item-header {
    min-height: 24px;
    margin: 0;
    gap: 8px;
}

.message.assistant-turn-with-process .timeline-item-time,
.message.progress-message .timeline-item-time {
    display: none;
}

.message.assistant-turn-with-process .timeline-item-title,
.message.progress-message .timeline-item-title {
    color: var(--text-secondary);
    font-size: 0.86rem;
    font-weight: 500;
    line-height: 1.55;
}

.message.assistant-turn-with-process .timeline-item-iteration .timeline-item-title,
.message.progress-message .timeline-item-iteration .timeline-item-title {
    color: var(--text-primary);
    font-weight: 600;
}

/* 主代理轮次是一次新的“模型决策 → 工具结果 → 继续决策”边界。
 * 用轻量横线把长执行过程分组；子代理步骤仍沿用普通时间线节点。 */
.message.assistant-turn-with-process .timeline-item-iteration.timeline-iteration-divider,
.message.progress-message .timeline-item-iteration.timeline-iteration-divider {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-top: 10px;
    padding-top: 12px !important;
    padding-bottom: 8px !important;
    overflow: visible;
    content-visibility: visible;
}

.message.assistant-turn-with-process .timeline-item-iteration.timeline-iteration-divider::after,
.message.progress-message .timeline-item-iteration.timeline-iteration-divider::after {
    content: "";
    flex: 1 1 48px;
    min-width: 28px;
    height: 1px;
    background: linear-gradient(
        90deg,
        color-mix(in srgb, var(--border-color) 88%, transparent),
        color-mix(in srgb, var(--border-color) 20%, transparent)
    );
}

.message.assistant-turn-with-process .timeline-item-iteration.timeline-iteration-divider .timeline-item-header,
.message.progress-message .timeline-item-iteration.timeline-iteration-divider .timeline-item-header {
    flex: 0 1 auto;
    min-width: 0;
    max-width: calc(100% - 40px);
}

.message.assistant-turn-with-process .timeline-item-iteration.timeline-iteration-divider .timeline-item-title,
.message.progress-message .timeline-item-iteration.timeline-iteration-divider .timeline-item-title {
    letter-spacing: 0.01em;
}

@media (max-width: 768px) {
    .message.assistant-turn-with-process .timeline-item-iteration.timeline-iteration-divider,
    .message.progress-message .timeline-item-iteration.timeline-iteration-divider {
        gap: 8px;
        margin-top: 7px;
    }

    .message.assistant-turn-with-process .timeline-item-iteration.timeline-iteration-divider::after,
    .message.progress-message .timeline-item-iteration.timeline-iteration-divider::after {
        flex-basis: 24px;
        min-width: 16px;
    }
}

.message.assistant-turn-with-process .timeline-item-content,
.message.progress-message .timeline-item-content {
    margin: 5px 0 2px;
    padding: 0;
    border: 0;
    color: var(--text-secondary);
    font-size: 0.84rem;
    line-height: 1.6;
}

.message.assistant-turn-with-process .timeline-item.tool-detail-collapsible .timeline-item-header::after,
.message.progress-message .timeline-item.tool-detail-collapsible .timeline-item-header::after {
    content: attr(data-tool-detail-label);
    margin-left: auto;
    padding-left: 12px;
    color: var(--text-muted);
    font-size: 0.72rem;
    font-weight: 500;
    white-space: nowrap;
}

.message.assistant-turn-with-process .tool-call-detail-content,
.message.progress-message .tool-call-detail-content {
    margin: 7px 0 4px;
    padding: 10px 12px;
    border: 1px solid color-mix(in srgb, var(--border-color) 78%, transparent);
    border-radius: 8px;
    background: color-mix(in srgb, var(--bg-secondary) 68%, transparent);
}

.message.assistant-turn-with-process .tool-args,
.message.assistant-turn-with-process .tool-result,
.message.progress-message .tool-args,
.message.progress-message .tool-result {
    border-color: color-mix(in srgb, var(--border-color) 82%, transparent);
    background: var(--bg-primary);
    font-size: 0.77rem;
}

/* Codex-style inline approval and audit state. */
.hitl-inline-approval.hitl-tool-approval-summary,
.hitl-inline-approval.hitl-inline-approval--merged {
    margin: 5px 0 4px;
    padding: 0;
    border: 0;
