    overflow: auto;
    border: 1px solid var(--border-color);
    border-radius: 8px;
    background: var(--bg-secondary);
    color: var(--text-primary);
    font-size: 0.75rem;
    white-space: pre-wrap;
    overflow-wrap: anywhere;
}

.hitl-inline-actions kbd {
    margin-left: 5px;
    padding: 1px 5px;
    border: 1px solid color-mix(in srgb, currentColor 22%, transparent);
    border-radius: 5px;
    background: color-mix(in srgb, currentColor 6%, transparent);
    color: inherit;
    font: inherit;
    font-size: 0.72em;
    opacity: 0.76;
}

.chat-hitl-approval-dock[hidden] {
    display: none !important;
}

.chat-input-container.has-hitl-approval .chat-composer-context,
.chat-input-container.has-hitl-approval .chat-composer-surface {
    display: none;
}

.chat-hitl-approval-dock {
    position: relative;
    z-index: 4;
    display: block;
    width: 100%;
    min-height: 158px;
    max-height: min(62vh, 560px);
    max-height: min(62dvh, 560px);
    padding: 18px 20px 74px;
    overflow: hidden;
    overscroll-behavior: contain;
    border: 1px solid rgba(15, 23, 42, 0.14);
    border-radius: 24px;
    background: rgba(255, 255, 255, 0.985);
    box-shadow: 0 16px 40px rgba(15, 23, 42, 0.11), 0 2px 8px rgba(15, 23, 42, 0.05);
    box-sizing: border-box;
    outline: none;
}

.chat-hitl-approval-scroll-region {
    min-height: 0;
    max-height: max(76px, calc(min(62vh, 560px) - 94px));
    max-height: max(76px, calc(min(62dvh, 560px) - 94px));
    overflow-y: auto;
    overscroll-behavior: contain;
    scroll-padding-bottom: 12px;
    scrollbar-gutter: stable;
}

.chat-hitl-approval-dock .hitl-codex-tool-row {
    font-size: 0.92rem;
}

.chat-hitl-approval-dock .hitl-approval-heading,
.chat-hitl-approval-dock .hitl-approval-primary,
.chat-hitl-approval-dock .hitl-approval-countdown,
.chat-hitl-approval-dock .hitl-inline-body,
.chat-hitl-approval-dock .hitl-inline-actions {
    margin-left: 26px;
}

.chat-hitl-approval-dock .hitl-approval-heading h3 {
    display: -webkit-box;
    max-width: 900px;
    overflow: hidden;
    font-size: 1rem;
    -webkit-box-orient: vertical;
    -webkit-line-clamp: 3;
}

.chat-hitl-approval-dock .hitl-inline-body {
    gap: 6px;
    margin-top: 10px;
    padding: 0;
}

.chat-hitl-approval-dock .hitl-edit-args {
    max-height: min(28vh, 220px);
    max-height: min(28dvh, 220px);
    overflow: auto;
    resize: vertical;
}

.chat-hitl-approval-dock .hitl-inline-actions {
    position: absolute;
    right: 20px;
    bottom: 16px;
    left: 20px;
    z-index: 2;
    min-height: 48px;
    justify-content: flex-end;
    gap: 8px;
    margin-top: 0;
    padding: 10px 0 0;
    border: 0;
    border-top: 1px solid color-mix(in srgb, var(--border-color) 70%, transparent);
    background: rgba(255, 255, 255, 0.985);
    box-shadow: none;
}

.chat-hitl-approval-dock .hitl-inline-status {
    margin-right: auto;
}

.chat-hitl-approval-dock .hitl-inline-approve,
.chat-hitl-approval-dock .hitl-inline-reject {
    min-height: 38px;
    padding: 8px 14px;
    border-radius: 999px;
}

:is(.hitl-inline-approval, .chat-hitl-approval-dock).hitl-approval-task-closed .hitl-pending-actions :is(button, .btn-primary, .btn-secondary) {
    border-color: #d1d5db !important;
    background: #e5e7eb !important;
    color: #9ca3af !important;
    box-shadow: none !important;
    cursor: not-allowed;
    opacity: 1;
}

html[data-theme="dark"] :is(.hitl-inline-approval, .chat-hitl-approval-dock).hitl-approval-task-closed .hitl-pending-actions :is(button, .btn-primary, .btn-secondary) {
    border-color: #374151 !important;
    background: #273244 !important;
    color: #7f8b9d !important;
}

html[data-theme="dark"] .chat-hitl-approval-dock {
    border-color: color-mix(in srgb, var(--border-color) 88%, transparent);
    background: color-mix(in srgb, var(--bg-primary) 97%, transparent);
    box-shadow: 0 18px 48px rgba(0, 0, 0, 0.28);
}

html[data-theme="dark"] .chat-hitl-approval-dock .hitl-inline-actions {
    border-color: color-mix(in srgb, var(--border-color) 70%, transparent) !important;
    background: color-mix(in srgb, var(--bg-primary) 97%, transparent) !important;
    box-shadow: none;
}

html[data-theme="dark"] .hitl-approval-primary code,
html[data-theme="dark"] .hitl-approval-details pre {
    border-color: rgba(148, 163, 184, 0.22);
    background: rgba(15, 23, 42, 0.5);
}

.hitl-codex-diff {
    margin: 4px 0 4px 25px;
    color: var(--text-secondary);
    font-size: 0.8rem;
}

.hitl-codex-diff summary {
    width: max-content;
    cursor: pointer;
}

.hitl-codex-diff pre {
    max-height: 220px;
    margin: 8px 0 0;
    padding: 10px;
    overflow: auto;
    border: 1px solid var(--border-color);
    border-radius: 8px;
    background: var(--bg-secondary);
    color: var(--text-primary);
    font-size: 0.76rem;
}

.hitl-tool-approval-summary .hitl-inline-body {
    gap: 8px;
    margin: 8px 0 0 25px;
    padding: 0;
}

.hitl-tool-approval-summary .hitl-inline-actions {
    justify-content: flex-end;
    gap: 7px;
    margin: 9px 0 0 25px;
    padding: 9px 0 0;
    border-top: 1px solid color-mix(in srgb, var(--border-color) 70%, transparent);
    background: transparent;
}

.hitl-tool-approval-summary .hitl-inline-actions .btn-primary,
.hitl-tool-approval-summary .hitl-inline-actions .btn-secondary {
    min-width: 0;
    min-height: 30px;
    padding: 5px 11px;
    border-radius: 7px;
    font-size: 0.79rem;
}

.hitl-tool-approval-summary .hitl-inline-status {
    margin-right: auto;
}

.hitl-tool-approval-summary .hitl-config-input,
.hitl-tool-approval-summary .hitl-edit-args {
    border-radius: 7px;
    background: var(--bg-primary);
}

html[data-theme="dark"] .message.assistant-turn-with-process .timeline-item::before,
html[data-theme="dark"] .message.progress-message .timeline-item::before {
    border-color: var(--bg-primary);
}

html[data-theme="dark"] .hitl-inline-approval.hitl-tool-approval-summary,
html[data-theme="dark"] .hitl-inline-approval.hitl-inline-approval--merged {
    border: 0;
    background: transparent;
    box-shadow: none;
}

@media (max-width: 760px) {
    .message.assistant-turn-with-process,
    .message.progress-message {
        gap: 8px;
    }

    .message.assistant-turn-with-process .message-content,
    .message.progress-message .message-content {
        flex-basis: calc(100% - 40px);
        max-width: calc(100% - 40px);
    }

    .message.assistant-turn-with-process .assistant-final-result {
        font-size: 0.93rem;
    }

    .message.assistant-turn-with-process .progress-timeline,
    .message.progress-message .progress-timeline {
        padding-left: 18px;
    }

    .message.assistant-turn-with-process .timeline-item,
    .message.progress-message .timeline-item {
        padding-left: 9px !important;
    }

    .message.assistant-turn-with-process .timeline-item.tool-detail-collapsible .timeline-item-header::after,
    .message.progress-message .timeline-item.tool-detail-collapsible .timeline-item-header::after {
        content: "›";
        font-size: 1rem;
    }

    .hitl-codex-explainer,
    .hitl-approval-heading,
    .hitl-approval-primary,
    .hitl-approval-countdown,
    .hitl-tool-approval-summary .hitl-inline-body,
    .hitl-tool-approval-summary .hitl-inline-actions,
    .hitl-codex-diff {
        margin-left: 0;
    }

    .hitl-tool-approval-summary .hitl-inline-actions {
        flex-wrap: wrap;
    }

    .chat-hitl-approval-dock {
        padding: 16px 16px 116px;
        border-radius: 18px;
    }

    .chat-hitl-approval-scroll-region {
        max-height: max(76px, calc(min(62vh, 560px) - 134px));
        max-height: max(76px, calc(min(62dvh, 560px) - 134px));
    }

    .chat-hitl-approval-dock .hitl-approval-heading,
    .chat-hitl-approval-dock .hitl-approval-primary,
    .chat-hitl-approval-dock .hitl-approval-countdown,
    .chat-hitl-approval-dock .hitl-inline-body,
    .chat-hitl-approval-dock .hitl-inline-actions {
        margin-left: 0;
    }

    .chat-hitl-approval-dock .hitl-inline-actions {
        right: 16px;
        bottom: 16px;
        left: 16px;
        flex-wrap: wrap;
    }

    .chat-hitl-approval-dock .hitl-inline-status {
        flex-basis: 100%;
        min-height: 0;
    }
}

@media (prefers-reduced-motion: reduce) {
    .project-task-status--running,
    .turn-process-status-dot.is-running,
    .hitl-codex-spinner {
        animation: none;
    }
}

/* A policy block is an intentional refusal before execution, separate from a tool failure. */
:root { --tool-blocked-color: #a65d08; }
html[data-theme="dark"] { --tool-blocked-color: #f4bc62; }
.tool-status-badge.tool-status-blocked,
.status-chip.status-blocked,
.monitor-status-chip.blocked,
.mcp-stats-kpi__chip.is-blocked,
.mcp-stats-tool-item__pill.is-blocked {
    color: var(--tool-blocked-color);
    background: rgba(217, 146, 36, .12);
    border: 1px solid rgba(217, 146, 36, .32);
}
.timeline-item-tool_call.tool-call-blocked,
.timeline-item-tool_result.tool-call-blocked {
    border: 1px solid rgba(217, 146, 36, .32);
    border-left: 3px solid var(--tool-blocked-color);
    background: rgba(217, 146, 36, .065);
}
.tool-result-section.blocked .tool-result,
#mcp-detail-modal .code-block.blocked,
.mcp-detail-btn[data-status="blocked"] {
    color: var(--text-primary);
    border-color: rgba(217, 146, 36, .32);
    background: rgba(217, 146, 36, .055);
}
.message.assistant-turn-with-process .timeline-item.tool-call-blocked::before,
.message.progress-message .timeline-item.tool-call-blocked::before {
    background: var(--tool-blocked-color);
}
.mcp-stats-blocked-note,
.mcp-stats-timeline-moment__blocked {
    color: var(--tool-blocked-color);
}
.mcp-stats-blocked-note { display: inline-block; margin-left: 8px; font-size: .75rem; }
.mcp-stats-timeline-bar-blocked { fill: #d99224; opacity: .8; }
.mcp-stats-timeline-bar-blocked.is-hover { opacity: 1; }
.mcp-stats-timeline-line--blocked { fill: none; stroke: #d99224; stroke-width: 1.5; }
.mcp-stats-timeline__legend-item--blocked::before { background: #d99224; }
.mcp-stats-rate.is-muted,
.mcp-stats-tool-item__rate.is-muted { color: var(--text-muted); }
